INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$ac3b3148-678f-541e-a4ba-6d618647818a$ml$::uuid, $ml$climatetech$ml$, 1, 1, $ml${"id": "climatetech-d1-c1", "title": "Three years above 1.5°C", "lessonTitle": "The climate science business needs", "slot": 1, "type": "apply", "brief": {"headline": "Copernicus put 2025 at 1.47°C above pre-industrial, the third warmest year on record. For the first time, a three-year period, 2023 to 2025, averaged above 1.5°C.", "kicker": "Apply the rule: is the Paris limit broken yet?", "fullText": "Europe's Copernicus climate service measured 2025 at 1.47°C above the 1850 to 1900 average. That was 0.13°C cooler than 2024, the warmest year on record at 1.60°C, and 0.01°C cooler than 2023.\n\nThe three years from 2023 to 2025 averaged above 1.5°C, a first. But the Paris limit is judged on long-term warming, which Copernicus puts at about 1.4°C. At the current rate, it says that long-term level could reach 1.5°C by the end of this decade.", "sources": [{"url": "https://www.ecmwf.int/en/about/media-centre/news/2025/2025-third-warmest-year", "label": "ECMWF, 2025 was the third-warmest year on record"}, {"url": "https://wmo.int/news/media-centre/wmo-confirms-2024-warmest-year-record-about-155degc-above-pre-industrial-level", "label": "WMO, 2024 warmest year on record"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Three straight years averaged above 1.5°C. Has the Paris limit been breached?", "options": ["Not yet: Paris counts long-term warming, now about 1.4°C", "Yes: any three-year run above 1.5°C breaks the Paris limit", "No: 2025 was cooler, so warming has stopped"], "correctIndex": 0, "explanation": "Paris is judged on long-term warming, about 1.4°C now. Three hot years are a warning, not the official breach."}, "numbers": {"kind": "numberSense", "prompt": "To the nearest tenth, how many degrees above pre-industrial was 2025?", "min": 0, "max": 2.5, "value": 1.5, "unit": "°C", "explanation": "About 1.47°C, third warmest on record, behind 2024 at 1.60°C and 2023 just above it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A climate risk team asks you in an interview whether the world has passed 1.5°C.", "prompt": "Which answer shows you have the basics exactly right?", "options": ["Yes, 2025 broke the Paris limit for good, as did 2024", "No, 2025 was cooler, so the trend reversed", "Single years have; the long-term level is about 1.4°C"], "correctIndex": 2, "consequences": ["Paris tracks decades, so one year cannot break it for good.", "A cooler year inside a warming trend is not a reversal.", "You separate single years from the long-term level, which they test for."], "explanation": "Precision builds trust: hot years crossed 1.5°C, the long-term average is about 1.4°C."}, "proReasoning": "A strong candidate quotes the number and the measurement window together. That shows they will not overstate or understate risk to a client.", "commonMistake": "Saying the Paris goal is lost, or that warming paused. Both mix up one year with the long-term trend.", "mentalModel": "Give the figure, then the window it is measured over."}, "invest": {"call": {"kind": "theCall", "situation": "You hold insurers and utilities. A colleague says 2025 cooled, so heat risk can drop in your models.", "prompt": "What do you tell them?", "options": ["Keep it: 2023 to 2025 was the hottest three-year run", "Agree: one cooler year lowers the long-run risk", "Wait a decade of data before changing anything"], "correctIndex": 0, "consequences": ["Your models track the trend, not one year.", "You cut risk right after the hottest three-year stretch.", "You let the models drift while the trend keeps rising."], "explanation": "2025 was still third warmest, and the three-year average topped 1.5°C. The trend, not one year, drives asset risk."}, "proReasoning": "Investors price the trend. A slightly cooler year inside a record three-year run does not lower long-term exposure.", "commonMistake": "Reacting to one data point. Climate risk is judged on averages over many years.", "mentalModel": "Price the trend, not the latest year."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells heat-stress alerts to warehouses. You are writing the first line of your pitch.", "prompt": "Which opening is both true and strong?", "options": ["2025 was the hottest year ever recorded", "2023 to 2025 averaged above 1.5°C, a first", "The world has now broken the Paris limit"], "correctIndex": 1, "consequences": ["2024 holds the record, so the first fact is already wrong.", "It is accurate, and the record still makes your point.", "Investors who know the science will doubt the rest of your deck."], "explanation": "The three-year average above 1.5°C is new, sourced and accurate. 2025 itself ranked third."}, "proReasoning": "Founders lead with a fact that survives checking. A precise record is more persuasive than a dramatic claim that falls apart.", "commonMistake": "Rounding up for effect. One wrong number makes investors question every other number.", "mentalModel": "Lead with the true record, not the scariest version."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that 2025 was cooler than 2024 and wonder if warming is slowing.", "prompt": "What's the better reading?", "options": ["Yes, it shows warming has started to reverse for good", "It means the 2024 record was a mistake", "Years vary, but the three-year average set a record"], "correctIndex": 2, "consequences": ["One cooler year inside a record run is not a reversal.", "2024 still stands as the warmest year measured.", "You read the trend through the year-to-year noise."], "explanation": "Single years bounce around. The long-term level keeps rising, about 1.4°C now."}, "proReasoning": "Look at multi-year averages. They show the direction that single years hide.", "commonMistake": "Treating each year as a verdict on the whole trend.", "mentalModel": "Read the average, not the single year."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e943a83fc0db$ml$]::text[]),
($ml$c41ae075-2356-52e1-83c7-abe107b104ba$ml$::uuid, $ml$climatetech$ml$, 1, 2, $ml${"id": "climatetech-d1-c2", "title": "From exhaust pipe to heatwave", "lessonTitle": "The climate science business needs", "slot": 2, "type": "connect", "brief": {"headline": "CO2 in the air reached 425.7 parts per million in 2025, 52% above pre-industrial levels. In 2024 the world was about 1.55°C warmer than the late 1800s.", "kicker": "Connect the two ideas: emissions, CO2 levels, then warming.", "fullText": "Burning coal, oil and gas adds CO2 to the air, which strengthens the greenhouse effect and traps heat. Fossil CO2 emissions hit a record 38.1 billion tonnes in 2025.\n\nThat pushed the concentration of CO2 to 425.7 parts per million, 52% above where it was before industry. The temperature followed: the WMO put 2024 at about 1.55°C above the 1850 to 1900 average, and the ten warmest years on record were 2015 to 2024.", "sources": [{"url": "https://globalcarbonbudget.org/fossil-fuel-co2-emissions-hit-record-high-in-2025/", "label": "Global Carbon Budget 2025"}, {"url": "https://science.nasa.gov/climate-change/", "label": "NASA, climate change"}, {"url": "https://wmo.int/news/media-centre/wmo-confirms-2024-warmest-year-record-about-155degc-above-pre-industrial-level", "label": "WMO, 2024 warmest year on record"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the chain from fuel to warming in order.", "steps": ["Power plants and cars burn coal, oil and gas", "CO2 is released into the air", "CO2 builds up, reaching 425.7 ppm in 2025", "A stronger greenhouse effect traps more heat", "Average temperatures rise, about 1.55°C by 2024"], "explanation": "Emissions drive the CO2 level, and the CO2 level drives warming. Each link feeds the next."}, "numbers": {"kind": "numberSense", "prompt": "CO2 is at 425.7 ppm, 52% above pre-industrial. Roughly what was the pre-industrial level?", "min": 0, "max": 500, "value": 280, "unit": "ppm", "explanation": "425.7 divided by 1.52 is about 280 ppm, the level before the industrial era."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A sustainability consultancy asks why cutting emissions takes years to show up in temperatures.", "prompt": "Which answer reflects the chain?", "options": ["Warming follows the CO2 stock, which keeps building", "Temperatures react to each year of emissions at once", "Emissions and temperatures are not connected"], "correctIndex": 0, "consequences": ["You explain that the stock of CO2 sets the warming.", "The heat follows the total CO2 built up, not one year.", "The link from emissions to warming is the core science."], "explanation": "Emissions add to a stock of CO2. The stock, now 425.7 ppm, drives warming."}, "proReasoning": "Explaining stocks and flows shows you can talk to clients about why targets matter long before results show.", "commonMistake": "Promising a client fast temperature results from a single year of cuts.", "mentalModel": "Flows fill the stock; the stock sets the heat."}, "invest": {"call": {"kind": "theCall", "situation": "An oil major says its emissions are flat, so its climate impact is not growing.", "prompt": "What is the flaw?", "options": ["Only rising emissions affect temperature", "Flat emissions still add to the CO2 stock", "Flat emissions mean CO2 levels are falling"], "correctIndex": 1, "consequences": ["Every tonne adds to warming, rising or not.", "You see that steady flows keep raising the stock.", "CO2 levels only fall when emissions drop far lower."], "explanation": "A flat flow into a tub keeps filling it. The CO2 level keeps climbing while emissions stay flat."}, "proReasoning": "Investors test claims against the chain. Flat emissions keep adding to the CO2 stock and to policy risk.", "commonMistake": "Treating flat emissions as zero impact.", "mentalModel": "Steady emissions still raise the stock."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are choosing where your climate startup should act on the chain.", "prompt": "Where does the root cause sit?", "options": ["At the end: the heat already in the air", "In the middle: measuring CO2 levels", "At the start: the fossil fuels being burned"], "correctIndex": 2, "consequences": ["Adapting to heat helps people but leaves the cause running.", "Measuring matters, but it does not cut a tonne by itself.", "Cutting fuel use works on the cause of everything after it."], "explanation": "Every later link starts with burning fuel. Cutting emissions works on the root cause."}, "proReasoning": "Founders who place their product on the chain can explain exactly which link they change.", "commonMistake": "Calling an adaptation or data product a fix for the cause.", "mentalModel": "Name the link you change."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a car in Ohio can heat the whole planet.", "prompt": "What is the simplest true answer?", "options": ["Its CO2 mixes into the whole atmosphere", "Its heat goes straight into the air", "It only warms the air near the road"], "correctIndex": 0, "consequences": ["CO2 spreads worldwide and traps heat everywhere.", "Engine heat is tiny next to the trapped heat.", "CO2 does not stay near where it came out."], "explanation": "CO2 mixes globally. Together, those emissions raised CO2 to 425.7 ppm."}, "proReasoning": "Think of CO2 as a blanket shared by everyone. Each tailpipe adds a little thickness.", "commonMistake": "Thinking warming comes from engine heat itself.", "mentalModel": "Emissions thicken a shared blanket."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:89c434e49c64$ml$]::text[]),
($ml$083e787f-bd9d-51bb-8819-1ad35d024409$ml$::uuid, $ml$climatetech$ml$, 1, 3, $ml${"id": "climatetech-d1-c3", "title": "The slide that says Paris is lost", "lessonTitle": "The climate science business needs", "slot": 3, "type": "decide", "brief": {"headline": "You lead sustainability at a food company. A draft board slide says the world broke the Paris goal in 2024. 2024 was about 1.55°C warmer than pre-industrial times.", "kicker": "Decide what the slide should say.", "fullText": "The WMO combined six datasets and put 2024 at 1.55°C above the 1850 to 1900 average, give or take 0.13°C. The ten warmest years on record were 2015 to 2024.\n\nBut the WMO stresses that one year above 1.5°C does not mean the Paris goal is lost, since that goal is measured over decades. Your board will use this slide to set budgets for heat and supply risk.", "sources": [{"url": "https://wmo.int/news/media-centre/wmo-confirms-2024-warmest-year-record-about-155degc-above-pre-industrial-level", "label": "WMO, 2024 warmest year on record"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these claims for the slide is false. Tap it.", "statements": ["2024 was about 1.55°C above pre-industrial.", "The ten warmest years on record were 2015 to 2024.", "One year above 1.5°C means the Paris goal is broken."], "fakeIndex": 2, "explanation": "Paris is measured over decades, so one hot year does not break it. The other two claims are the WMO's own."}, "numbers": {"kind": "numberSense", "prompt": "How many of the ten years from 2015 to 2024 rank among the ten warmest on record?", "min": 0, "max": 15, "value": 10, "unit": "years", "explanation": "All ten. That run is the trend the board should plan around, whatever one year shows."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager wrote the slide and asks you to check it before the board meeting.", "prompt": "How do you fix it?", "options": ["Delete the temperature figures entirely", "Keep 1.55°C, explain Paris is judged over decades", "Leave it as written, since the drama gets attention"], "correctIndex": 1, "consequences": ["The board loses the strongest evidence for the budget.", "The slide stays sharp and survives any expert question.", "A board member who knows the science loses trust in the team."], "explanation": "Correct the claim, keep the facts. Precision protects your team's credibility."}, "proReasoning": "Junior staff earn trust by fixing an error quietly and keeping the message strong.", "commonMistake": "Letting an overstatement through because it supports the budget you want.", "mentalModel": "Fix the claim, keep the evidence."}, "invest": {"call": {"kind": "theCall", "situation": "An investor reads the corrected slide and asks what it means for your supply chain.", "prompt": "What is the honest message?", "options": ["Paris is lost, so further action is pointless", "One hot year changes nothing for us", "Heat records are rising, so supply risk is rising"], "correctIndex": 2, "consequences": ["Giving up on cuts raises long-term risk for everyone.", "Ten record years in a row is a trend, not one year.", "You tie the trend to a concrete business risk."], "explanation": "The ten warmest years were 2015 to 2024. That trend is what affects crops and costs."}, "proReasoning": "Investors want the business link: rising heat means rising supply risk, priced over years.", "commonMistake": "Swinging between alarm and dismissal instead of stating the trend.", "mentalModel": "Trend first, then the business link."}, "build_startup": {"call": {"kind": "theCall", "situation": "A startup pitches you crop heat sensors with a slide saying Paris is already lost.", "prompt": "What do you make of it?", "options": ["The product may be good, the claim is wrong", "The claim proves they know the science", "Reject them, since heat risk is not real"], "correctIndex": 0, "consequences": ["You judge the product on its merits and note the error.", "Overclaiming shows they did not check the basics.", "Ten record years in a row says heat risk is real."], "explanation": "The heat trend is real. The Paris claim is not. Both things can be true of one pitch."}, "proReasoning": "Separate the problem a founder solves from the way they describe it. Accurate framing is a signal of care.", "commonMistake": "Accepting a dramatic claim because you agree with the cause.", "mentalModel": "Judge the product, check the claim."}, "curiosity": {"call": {"kind": "theCall", "situation": "A headline says Paris died in 2024. You want to know if that is fair.", "prompt": "What's the fair summary?", "options": ["2024 was a normal year, and nothing really changed", "2024 crossed 1.5°C; Paris is judged over decades", "The headline is right, the goal is gone"], "correctIndex": 1, "consequences": ["It was the warmest year on record.", "You hold both facts at once, which is the accurate view.", "The WMO itself says one year does not settle it."], "explanation": "A record year above 1.5°C, and a goal measured over decades: both are true."}, "proReasoning": "When a headline sounds final, ask what time window the goal is measured over.", "commonMistake": "Taking one year as the end of the story.", "mentalModel": "Ask what window the goal uses."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:69725707a2b8$ml$]::text[]),
($ml$b64d2a5c-b8bc-56a2-a427-b439493fb179$ml$::uuid, $ml$climatetech$ml$, 2, 1, $ml${"id": "climatetech-d2-c1", "title": "Where $2.1 trillion went", "lessonTitle": "Where the money in climate goes", "slot": 1, "type": "apply", "brief": {"headline": "Global energy transition investment passed $2 trillion for the first time in 2024, BloombergNEF found: $2.1 trillion, up 11%. China alone invested $818 billion.", "kicker": "Apply the rule: what does the money say about direction?", "fullText": "BloombergNEF counted $757 billion for electrified transport, the largest category, then $728 billion for renewable energy and $390 billion for power grids. China invested $818 billion, up 20% from 2023.\n\nGrowth slowed compared with the previous three years. BNEF estimates the world needs about $5.6 trillion a year from 2025 to 2030 to stay on track for net zero by 2050.", "sources": [{"url": "https://about.bnef.com/blog/global-investment-in-the-energy-transition-exceeded-2-trillion-for-the-first-time-in-2024-according-to-bloombergnef-report", "label": "BloombergNEF, energy transition investment passed $2 trillion in 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "Which category drew more transition money in 2024?", "left": {"name": "Electrified transport", "note": "Electric cars, buses and charging"}, "right": {"name": "Renewable energy", "note": "Solar and wind farms"}, "correctIndex": 0, "explanation": "Electrified transport drew $757 billion, just ahead of renewable energy at $728 billion."}, "numbers": {"kind": "numberSense", "prompt": "BNEF says $5.6 trillion a year is needed. About what share of that did 2024 reach?", "min": 0, "max": 100, "value": 38, "unit": "%", "explanation": "$2.1 trillion out of $5.6 trillion is about 38%. Record money, but well short of the need."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A climate fund interviewer asks which sector led energy transition investment in 2024.", "prompt": "What do you answer?", "options": ["Electrified transport, at about $757 billion", "Renewables, since solar leads every chart", "Grids, since they connect everything"], "correctIndex": 0, "consequences": ["You cite the right sector with its figure.", "Renewables were close behind at $728 billion, but second.", "Grids drew $390 billion, about half the leader."], "explanation": "BNEF's count put electric transport first, renewables second and grids third."}, "proReasoning": "Quoting the top categories with figures shows you follow the capital, not just the headlines.", "commonMistake": "Assuming solar always leads. It depends on whose count and which categories.", "mentalModel": "Know the top three with their numbers."}, "invest": {"call": {"kind": "theCall", "situation": "You see $2.1 trillion invested against $5.6 trillion needed each year.", "prompt": "What does the gap suggest?", "options": ["The gap means the goal is impossible", "Demand for capital will keep growing", "The sector is overfunded and due to shrink"], "correctIndex": 1, "consequences": ["A gap is a target to close, not a verdict.", "You read the gap as room for more investment.", "Investment is under half of the stated need."], "explanation": "Investment covered about 38% of the estimated need, so capital demand has room to grow."}, "proReasoning": "Investors compare flows with needs. A large gap points to where future money must go.", "commonMistake": "Reading a record number as proof the market is saturated.", "mentalModel": "Compare what is spent with what is needed."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup could sell to grid operators or to EV fleets.", "prompt": "What does the money flow tell you?", "options": ["Grid operators, since grids drew the most money", "Neither, since investment growth slowed", "EV transport has the most spending to sell into"], "correctIndex": 2, "consequences": ["Grids drew $390 billion, about half of transport.", "Slower growth on $2.1 trillion is still huge demand.", "You aim at the largest pool of spending."], "explanation": "Electrified transport drew $757 billion, the biggest single pool of customers' spending."}, "proReasoning": "Founders size markets by where buyers already spend. The biggest category has the most budgets to win.", "commonMistake": "Ignoring a market because growth slowed while the base is enormous.", "mentalModel": "Follow where buyers already spend."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder which country spends the most on the energy transition.", "prompt": "What did BNEF find?", "options": ["China, with $818 billion in 2024", "The US, with most of the total", "Europe, ahead of every other region"], "correctIndex": 0, "consequences": ["China invested about two fifths of the global total.", "The US was well behind China.", "China outspent Europe."], "explanation": "China invested $818 billion, up 20%, out of $2.1 trillion worldwide."}, "proReasoning": "Look at who spends, not just how much. One country can shape the whole market.", "commonMistake": "Assuming the biggest economy spends the most.", "mentalModel": "Check who writes the biggest checks."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a9ac136d8de3$ml$]::text[]),
($ml$a4b18c0b-aabe-5fbc-8e35-e8cfbcc32cc0$ml$::uuid, $ml$climatetech$ml$, 2, 2, $ml${"id": "climatetech-d2-c2", "title": "Record money, record emissions", "lessonTitle": "Where the money in climate goes", "slot": 2, "type": "connect", "brief": {"headline": "In 2025, $2.2 trillion went into clean energy, twice the $1.1 trillion for fossil fuels. The same year, fossil CO2 emissions hit a record 38.1 billion tonnes.", "kicker": "Connect day 1 and day 2: why money and emissions both rose.", "fullText": "The IEA expected $3.3 trillion of energy investment in 2025: $2.2 trillion clean and $1.1 trillion fossil. Solar alone drew about $450 billion.\n\nYet the Global Carbon Budget found fossil emissions rose 1.1% to a record. Investment shows where the system is heading, but the existing fleet of fossil plants and engines keeps running for years, so emissions lag the money.", "sources": [{"url": "https://sustainabilitymag.com/articles/iea-report-2025-clean-energy-investment-to-reach-us-2-2tn", "label": "Sustainability Magazine on IEA World Energy Investment 2025"}, {"url": "https://globalcarbonbudget.org/fossil-fuel-co2-emissions-hit-record-high-in-2025/", "label": "Global Carbon Budget 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Clean energy drew twice the fossil investment in 2025.", "Fossil CO2 emissions fell in 2025 thanks to clean investment.", "Existing fossil plants keep running while new money goes clean."], "fakeIndex": 1, "explanation": "Fossil emissions rose 1.1% to a record 38.1 billion tonnes, even as clean money doubled fossil money."}, "numbers": {"kind": "numberSense", "prompt": "Clean energy drew $2.2 trillion and fossil fuels $1.1 trillion. How many times larger is clean?", "min": 0, "max": 5, "value": 2, "unit": "x", "explanation": "Twice as large. The ratio shows direction, while the emissions record shows the lag."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview you are asked how clean investment can double fossil while emissions hit a record.", "prompt": "What is the best explanation?", "options": ["Clean energy raises emissions", "Old fossil assets keep running as new ones go clean", "One of the two sets of figures must simply be wrong"], "correctIndex": 1, "consequences": ["Clean energy replaces fossil output over time.", "You explain the lag between flows and the installed base.", "Both figures come from major sources and are consistent."], "explanation": "New money shifts the future mix. The existing fleet sets this year's emissions."}, "proReasoning": "Explaining the lag between investment and emissions shows you understand how energy systems turn over.", "commonMistake": "Claiming one number must be wrong because they seem to clash.", "mentalModel": "Investment moves the future; the fleet sets today."}, "invest": {"call": {"kind": "theCall", "situation": "Emissions hit a record. A client asks if that means clean energy stocks are failing.", "prompt": "What do you say?", "options": ["Yes: record emissions prove clean energy failed", "Sell both, since the picture is unclear", "No: they are growing, but fossil assets still run"], "correctIndex": 2, "consequences": ["Clean investment doubled fossil, which is not failure.", "Unclear is not a reason to exit a growing sector.", "You keep the growth story separate from the emissions lag."], "explanation": "Clean energy drew twice fossil investment. Emissions lag because old assets keep operating."}, "proReasoning": "Investors separate the growth of a sector from total system outcomes that move slowly.", "commonMistake": "Judging a sector by a global number it does not control alone.", "mentalModel": "Separate sector growth from system lag."}, "build_startup": {"call": {"kind": "theCall", "situation": "You see that old fossil plants keep emissions high despite clean investment.", "prompt": "Which startup idea attacks that lag?", "options": ["Tools that speed up retiring or replacing old assets", "Another solar panel brand for the crowded market", "Ads promoting climate awareness"], "correctIndex": 0, "consequences": ["You target the bottleneck that keeps emissions high.", "Solar already draws $450 billion; the lag is elsewhere.", "Awareness does not retire a single plant."], "explanation": "The lag sits in the existing fleet. Speeding its turnover cuts emissions sooner."}, "proReasoning": "Founders look for the bottleneck between money and results. Here it is the old installed base.", "commonMistake": "Crowding into the most funded category instead of the bottleneck.", "mentalModel": "Find where money fails to become results."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read both headlines in one week and feel confused.", "prompt": "How do they fit together?", "options": ["Clean energy secretly runs on coal", "New clean energy adds up; old fossil use fades slowly", "One of the two reports must be written as propaganda"], "correctIndex": 1, "consequences": ["Clean sources replace fossil output over time.", "You see both trends at once.", "Both are mainstream, well sourced reports."], "explanation": "Money shows direction. Emissions show the system that is still running."}, "proReasoning": "When two true facts seem to clash, look for a time lag between them.", "commonMistake": "Picking one headline and dismissing the other.", "mentalModel": "Look for the lag."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d6338a4380a5$ml$]::text[]),
($ml$2950301b-2130-5257-a6c2-d7a2252bf0d6$ml$::uuid, $ml$climatetech$ml$, 2, 3, $ml${"id": "climatetech-d2-c3", "title": "Pick your first market", "lessonTitle": "Where the money in climate goes", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup that makes software for building energy projects. You must pick one market to sell into first. Solar drew about $450 billion in 2025, the largest single category.", "kicker": "Decide where to sell first.", "fullText": "The IEA expected $2.2 trillion of clean energy investment in 2025, against $1.1 trillion for fossil fuels. Solar was the biggest single category at about $450 billion.\n\nChina is by far the largest energy investor, spending twice as much as the European Union. Your team can support one market well this year.", "sources": [{"url": "https://sustainabilitymag.com/articles/iea-report-2025-clean-energy-investment-to-reach-us-2-2tn", "label": "Sustainability Magazine on IEA World Energy Investment 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is this spending clean energy or fossil fuels?", "buckets": ["Clean energy", "Fossil fuels"], "items": [{"text": "A new solar farm", "bucket": 0}, {"text": "Grid lines for wind power", "bucket": 0}, {"text": "A new offshore oil platform", "bucket": 1}, {"text": "Expanding a coal mine", "bucket": 1}, {"text": "Battery storage at a substation", "bucket": 0}], "explanation": "Solar, grids and storage count as clean. Oil and coal supply are fossil investment."}, "numbers": {"kind": "numberSense", "prompt": "Solar drew $450 billion of $2.2 trillion in clean energy. About what share is that?", "min": 0, "max": 100, "value": 20, "unit": "%", "explanation": "About 20%. One technology took a fifth of all clean energy money."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join this startup in sales. The founder asks which customer list you would build first.", "prompt": "Where do you start?", "options": ["Coal operators, since they need help most", "Every energy sector at once", "Solar developers, where the most money flows"], "correctIndex": 2, "consequences": ["Coal spending is shrinking relative to clean.", "Spreading thin means winning no one.", "You go where budgets are largest."], "explanation": "Solar was the single largest category at about $450 billion."}, "proReasoning": "Good sales hires pick a focused list where budgets already exist.", "commonMistake": "Chasing every sector, which leaves no time to win any.", "mentalModel": "Focus on the biggest budgets first."}, "invest": {"call": {"kind": "theCall", "situation": "You are deciding whether to fund this startup. It targets solar first.", "prompt": "What do you check?", "options": ["Whether it can win share in a crowded large market", "Only the total size of the solar market each year", "Whether fossil fuels will vanish next year"], "correctIndex": 0, "consequences": ["Big markets attract rivals, so you test the edge.", "Size alone does not tell you who wins.", "Fossil spending is still $1.1 trillion."], "explanation": "A $450 billion category draws competitors. The question is this team's advantage."}, "proReasoning": "Investors pair market size with competitive edge. The largest category is also the most contested.", "commonMistake": "Funding a startup because its market is big, not because it can win.", "mentalModel": "Big market, then ask why this team wins."}, "build_startup": {"call": {"kind": "theCall", "situation": "You can support one market well this year.", "prompt": "Which do you pick?", "options": ["A tiny niche with no buyers yet", "Solar, the largest single category of spend", "Fossil fuels, since they get half as much"], "correctIndex": 1, "consequences": ["No buyers means no first revenue.", "You start where the most projects are being built.", "Fossil investment is half the clean total and shrinking in share."], "explanation": "Follow the investment: solar's $450 billion means the most projects needing your software."}, "proReasoning": "Where money flows, needs follow. Starting in the largest category gives the most chances to sell.", "commonMistake": "Picking a market for its story instead of its spending.", "mentalModel": "Start where the projects are."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear solar got more money than any other energy type.", "prompt": "How much was it in 2025?", "options": ["About $45 billion", "About $4.5 trillion", "About $450 billion"], "correctIndex": 2, "consequences": ["That is ten times too small.", "That is more than all energy investment combined.", "About a fifth of all clean energy money."], "explanation": "About $450 billion, out of $3.3 trillion of total energy investment."}, "proReasoning": "Anchor big numbers against a total. $450 billion of $3.3 trillion is easy to remember.", "commonMistake": "Mixing up billions and trillions.", "mentalModel": "Anchor each number to the total."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:79d6fba4f680$ml$]::text[]),
($ml$55cfa7cb-5365-5821-8a5e-8576fdbfc506$ml$::uuid, $ml$climatetech$ml$, 3, 1, $ml${"id": "climatetech-d3-c1", "title": "China's flat line", "lessonTitle": "Who holds the power over emissions", "slot": 1, "type": "apply", "brief": {"headline": "China's CO2 emissions have been flat or falling for 18 months, since March 2024, a Carbon Brief analysis found. China emits about 32% of the world's fossil CO2.", "kicker": "Apply the rule: what happens when the biggest emitter stalls?", "fullText": "In the third quarter of 2025, China's emissions were unchanged from a year earlier. Solar generation rose 46% and wind 11%, and clean sources covered almost 90% of a 6.1% rise in power demand. Transport emissions fell about 5% as electric vehicles spread, and cement fell 7% with the property slump.\n\nThe chemical industry pushed the other way, with a large rise. China added 240 GW of solar and 61 GW of wind in the first nine months of 2025.", "sources": [{"url": "https://www.carbonbrief.org/analysis-chinas-co2-emissions-have-now-been-flat-or-falling-for-18-months/", "label": "Carbon Brief, China's CO2 flat or falling for 18 months"}, {"url": "https://www.cger.nies.go.jp/gcp/pdf/20251113/CarbonBudget2025_CICERO_press_E.pdf", "label": "CICERO, Global Carbon Budget 2025 release"}]}, "evidence": {"kind": "sortSignal", "prompt": "Did this push China's CO2 down or up in 2025?", "buckets": ["Pushed CO2 down", "Pushed CO2 up"], "items": [{"text": "Solar generation up 46%", "bucket": 0}, {"text": "Electric vehicles cutting transport fuel", "bucket": 0}, {"text": "Cement output falling with the property slump", "bucket": 0}, {"text": "A large rise in the chemical industry", "bucket": 1}, {"text": "Oil use outside transport up about 10%", "bucket": 1}], "explanation": "Clean power, EVs and less cement pulled emissions down. Chemicals and non-transport oil pushed them up."}, "numbers": {"kind": "numberSense", "prompt": "About what share of China's 2025 power demand growth did clean sources cover?", "min": 0, "max": 100, "value": 90, "unit": "%", "explanation": "Almost 90%, which is why power sector emissions stayed flat despite strong demand."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A clean energy firm asks why China matters more than any other country for global emissions.", "prompt": "Which answer is sharpest?", "options": ["Its emissions are already falling fast every year", "It emits about 32%, so its trend moves the total", "It has the most climate laws"], "correctIndex": 1, "consequences": ["They are flat or slightly falling, not falling fast.", "You tie China's share to its effect on the global total.", "Influence comes from the size of its emissions."], "explanation": "A third of the world's fossil CO2 means China's trend moves the global line."}, "proReasoning": "Pair the share with the trend: 32% of emissions, flat for 18 months. That is the story analysts watch.", "commonMistake": "Overstating the fall. Flat or falling is a turning point, not a collapse.", "mentalModel": "Share first, then the trend."}, "invest": {"call": {"kind": "theCall", "situation": "You track coal miners exposed to China's power sector.", "prompt": "What does the analysis signal?", "options": ["Coal demand will surge with power demand", "Nothing, since emissions were flat", "Clean power is now meeting most new demand"], "correctIndex": 2, "consequences": ["Clean sources covered almost 90% of the demand rise.", "Flat emissions with rising demand is the signal.", "You see that growth is going to clean sources."], "explanation": "Demand rose 6.1% while power emissions stayed flat. New demand is going to solar and wind."}, "proReasoning": "Investors watch where marginal demand goes. If clean power meets nearly all new demand, fossil growth stalls.", "commonMistake": "Assuming rising power demand means rising coal use.", "mentalModel": "Follow where the new demand goes."}, "build_startup": {"call": {"kind": "theCall", "situation": "You make industrial heat pumps. China's chemical sector kept growing its emissions.", "prompt": "What does that tell you?", "options": ["Industry is where China's cuts are lagging", "China has solved its emissions already", "Chemicals are too small to matter"], "correctIndex": 0, "consequences": ["You spot the sector still pushing emissions up.", "Flat totals hide sectors still rising.", "The chemical rise offset cuts elsewhere."], "explanation": "Power was flat thanks to clean energy. Chemicals were the sector pushing emissions up."}, "proReasoning": "Founders look inside a total for the sector going the wrong way. That is where demand for solutions grows.", "commonMistake": "Reading a flat total as a solved problem.", "mentalModel": "Look for the sector still rising."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear China might have peaked its emissions.", "prompt": "What's the careful version?", "options": ["Still rising faster than ever", "Flat or falling for 18 months; not yet confirmed", "Peaked for certain, and now falling fast each year"], "correctIndex": 1, "consequences": ["Emissions have not risen since March 2024.", "You match the evidence: a long flat stretch.", "The analysis calls 2025 finely balanced."], "explanation": "Carbon Brief found 18 months flat or falling. A confirmed peak needs more data."}, "proReasoning": "Turning points are confirmed in hindsight. Describe what the data shows so far.", "commonMistake": "Calling a peak before the data settles it.", "mentalModel": "Describe what the data shows so far."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:832b39573709$ml$]::text[]),
($ml$e176b62f-2a6a-5f5f-8a1f-a77e05dcd658$ml$::uuid, $ml$climatetech$ml$, 3, 2, $ml${"id": "climatetech-d3-c2", "title": "Biggest spender, biggest emitter", "lessonTitle": "Who holds the power over emissions", "slot": 2, "type": "connect", "brief": {"headline": "China invests twice as much in energy as the European Union. It also emits about 32% of global fossil CO2, against 6% for the EU.", "kicker": "Connect day 2 and day 3: where money and emissions overlap.", "fullText": "The IEA found China is by far the largest energy investor, spending twice as much as the EU. The Global Carbon Budget 2025 puts China at 32% of fossil CO2, the US at 13%, India at 8% and the EU at 6%.\n\nTogether, those four emit about 59% of the world's fossil CO2. The country that invests the most is also the one whose choices move global emissions the most.", "sources": [{"url": "https://sustainabilitymag.com/articles/iea-report-2025-clean-energy-investment-to-reach-us-2-2tn", "label": "Sustainability Magazine on IEA World Energy Investment 2025"}, {"url": "https://www.cger.nies.go.jp/gcp/pdf/20251113/CarbonBudget2025_CICERO_press_E.pdf", "label": "CICERO, Global Carbon Budget 2025 release"}]}, "evidence": {"kind": "multipleChoice", "prompt": "China invests twice as much as the EU and emits about five times as much. What follows?", "options": ["The EU, not China, sets the global emissions trend", "Investment and emissions are unrelated", "China's energy choices move global emissions the most"], "correctIndex": 2, "explanation": "China is both the largest investor and the largest emitter, so its choices move the global total."}, "numbers": {"kind": "numberSense", "prompt": "China emits 32% of fossil CO2 and the US 13%. About how many times more is China?", "min": 0, "max": 6, "value": 2.5, "unit": "x", "explanation": "32 divided by 13 is about 2.5. China emits roughly two and a half times as much as the US."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a firm that sells clean tech to Asia. They ask why China is central to their plan.", "prompt": "What do you say?", "options": ["It has the smallest energy market of the big economies", "It emits less than the EU", "It is the top energy investor and the top emitter"], "correctIndex": 2, "consequences": ["China is the largest energy investor.", "China emits about 32%, the EU about 6%.", "You link spending and emissions in one answer."], "explanation": "China spends twice what the EU does on energy and emits about five times as much CO2."}, "proReasoning": "Linking a market's spending to its emissions shows you see both the opportunity and the impact.", "commonMistake": "Discussing climate impact without the market size behind it.", "mentalModel": "Pair spending with emissions."}, "invest": {"call": {"kind": "theCall", "situation": "You are weighing a clean energy fund focused on Europe against one focused on China.", "prompt": "What is the key difference?", "options": ["China's market is bigger and moves global emissions", "Europe invests more in energy each year than China", "There is no meaningful difference"], "correctIndex": 0, "consequences": ["You compare scale and climate weight together.", "China invests twice what the EU does.", "The two differ in size and in emissions share."], "explanation": "Twice the investment and about five times the emissions: the two markets carry very different weight."}, "proReasoning": "Investors compare scale and policy weight. A market that moves global emissions shapes global demand too.", "commonMistake": "Treating all large markets as equal in climate weight.", "mentalModel": "Weigh scale and emissions together."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your product cuts factory emissions. You must decide where its impact would be largest.", "prompt": "Where do you aim?", "options": ["Wherever the competition is the lowest", "Where emissions and investment are largest", "Where emissions are smallest"], "correctIndex": 1, "consequences": ["Low competition can mean low demand.", "You put your product where it cuts the most tonnes.", "Small emitters offer small impact."], "explanation": "China combines the largest emissions share with the largest energy investment."}, "proReasoning": "Impact scales with the emissions you can reach. Big emitters with big budgets offer both.", "commonMistake": "Choosing a market for ease rather than impact and demand.", "mentalModel": "Aim where tonnes and budgets are largest."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder whether China is a climate villain or a climate leader.", "prompt": "What do the numbers say?", "options": ["Only a villain, it never invests", "Only a leader, its emissions are tiny", "Both: top emitter and top clean investor"], "correctIndex": 2, "consequences": ["China is the largest energy investor.", "China emits about a third of fossil CO2.", "You hold both facts at once."], "explanation": "China emits the most and invests the most. Both are true."}, "proReasoning": "Big countries often lead in both the problem and the solution. Check both columns.", "commonMistake": "Forcing a country into one box.", "mentalModel": "Check both the problem and the spending."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8c0688a2c4f3$ml$]::text[]),
($ml$dcaeae2b-a98b-51ae-9c33-ea5442686b8e$ml$::uuid, $ml$climatetech$ml$, 3, 3, $ml${"id": "climatetech-d3-c3", "title": "One voice or a coalition", "lessonTitle": "Who holds the power over emissions", "slot": 3, "type": "decide", "brief": {"headline": "You advise a mid-sized country that emits under 1% of global CO2. Its leaders want the most climate influence. China, the US, India and the EU emit about 59% of the total.", "kicker": "Decide how a small emitter gets influence.", "fullText": "The Global Carbon Budget 2025 puts China at 32% of fossil CO2, the US at 13%, India at 8% and the EU27 at 6%. The rest of the world, more than 150 countries, emits about 41%.\n\nProjected 2025 changes: China up 0.4%, the US up 1.9%, India up 1.4% and the EU up 0.4%. Your country's own cuts barely move the total.", "sources": [{"url": "https://www.cger.nies.go.jp/gcp/pdf/20251113/CarbonBudget2025_CICERO_press_E.pdf", "label": "CICERO, Global Carbon Budget 2025 release"}, {"url": "https://globalcarbonbudget.org/fossil-fuel-co2-emissions-hit-record-high-in-2025/", "label": "Global Carbon Budget 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Four emitters produce about 59% of fossil CO2.", "The US was projected to emit 1.9% more in 2025.", "The EU emits more fossil CO2 than India."], "fakeIndex": 2, "explanation": "India emits about 8% and the EU about 6%, so India emits more."}, "numbers": {"kind": "numberSense", "prompt": "The four biggest emitters produce 59% of fossil CO2. What share comes from everyone else?", "min": 0, "max": 100, "value": 41, "unit": "%", "explanation": "About 41%, spread across more than 150 countries."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a junior diplomat. Your minister asks how to be heard at the next climate summit.", "prompt": "What do you recommend?", "options": ["Join a bloc that presses the big emitters", "Make a bold solo pledge and hope", "Skip the summit since you are small"], "correctIndex": 0, "consequences": ["A coalition gives you weight the big four must answer.", "A solo pledge from under 1% moves little.", "Absence gives up the little influence you have."], "explanation": "Four emitters hold 59% of the outcome. Small countries gain weight together."}, "proReasoning": "Good advisers match strategy to weight. A small emitter gains influence through coalitions.", "commonMistake": "Assuming a strong national pledge alone shifts global talks.", "mentalModel": "Small emitters gain weight together."}, "invest": {"call": {"kind": "theCall", "situation": "You run a fund. Which countries' policies should drive your clean tech demand forecast?", "prompt": "Where do you look first?", "options": ["Any country with a net zero target", "China, the US, India and the EU", "Small countries with bold pledges"], "correctIndex": 1, "consequences": ["A target matters less than the size behind it.", "Their policies cover about 59% of emissions and set demand.", "Bold pledges from small emitters move little demand."], "explanation": "The big four emit about 59%. Their policies shape most clean tech demand."}, "proReasoning": "Investors weight policy by the size of the market behind it.", "commonMistake": "Building a forecast on headline pledges from small markets.", "mentalModel": "Weight policy by market size."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're a founder in this small country. Your product cuts emissions in cement plants.", "prompt": "Where should you plan to grow?", "options": ["Stay home, since the market is safe", "Wait until big emitters regulate cement", "Prove it at home, then sell to big emitters"], "correctIndex": 2, "consequences": ["Your home market is too small to matter much.", "Waiting hands the market to others.", "A home pilot opens doors to the markets with scale."], "explanation": "The emissions, and the buyers, sit mostly in the four big emitters."}, "proReasoning": "Founders in small markets use home as a proving ground for export to big emitters.", "commonMistake": "Building only for a market that holds a tiny share of emissions.", "mentalModel": "Prove it small, sell it big."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder whether small countries can affect climate at all.", "prompt": "What's the honest answer?", "options": ["Together they emit 41% and gain influence", "No, only China matters", "Yes, any one country can fix it alone"], "correctIndex": 0, "consequences": ["Many small emitters add up, and blocs carry weight.", "Everyone outside the big four still emits 41%.", "No single country emits enough to fix it alone."], "explanation": "Outside the big four, countries emit about 41% and gain influence in groups."}, "proReasoning": "Shares add up. Small emitters matter together, even if none matters alone.", "commonMistake": "Concluding that only the largest emitter counts.", "mentalModel": "Small shares add up."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:253d22668004$ml$]::text[]),
($ml$df133d04-97fa-5497-b516-cb1d30d55fd2$ml$::uuid, $ml$climatetech$ml$, 4, 1, $ml${"id": "climatetech-d4-c1", "title": "Three years of budget left", "lessonTitle": "The numbers that frame climate risk", "slot": 1, "type": "apply", "brief": {"headline": "More than 60 scientists estimated 130 billion tonnes of CO2 left for 1.5°C from the start of 2025. At current emissions, that lasts a little more than three years.", "kicker": "Apply the rule: what does a shrinking budget mean for timing?", "fullText": "The Indicators of Global Climate Change report, led from the University of Leeds, put the remaining 1.5°C budget at 130 billion tonnes of CO2. Emissions have averaged about 53 billion tonnes of CO2 equivalent a year over the past decade.\n\nObserved warming in 2024 was about 1.52°C, of which about 1.36°C was caused by humans. Human-caused warming is rising about 0.27°C per decade. The Global Carbon Budget gives a different estimate, about 170 billion tonnes, but both say the budget is nearly gone.", "sources": [{"url": "https://climate.leeds.ac.uk/news/scientists-find-three-years-left-of-remaining-carbon-budget-for-1-5c/", "label": "University of Leeds, three years left of the 1.5C carbon budget"}, {"url": "https://globalcarbonbudget.org/fossil-fuel-co2-emissions-hit-record-high-in-2025/", "label": "Global Carbon Budget 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which estimate leaves less time to stay within 1.5°C?", "left": {"name": "Indicators of Global Climate Change", "note": "130 billion tonnes from the start of 2025"}, "right": {"name": "Global Carbon Budget", "note": "170 billion tonnes, about four years"}, "correctIndex": 0, "explanation": "130 billion tonnes lasts a little over three years. Both estimates point to a budget that is nearly used up."}, "numbers": {"kind": "numberSense", "prompt": "Human warming is 1.36°C and rising 0.27°C a decade. About how many years until 1.5°C?", "min": 0, "max": 20, "value": 5, "unit": "years", "explanation": "0.14°C to go at 0.27°C a decade is about half a decade, roughly five years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A client asks why your budget figure differs from one they read elsewhere.", "prompt": "How do you answer?", "options": ["Ours is right, so theirs must be wrong", "Budgets are only guesses, so ignore them both", "Estimates differ, but all show it nearly used up"], "correctIndex": 2, "consequences": ["Both come from serious scientific groups.", "Both estimates point to a few years at most.", "You explain the range and keep the message clear."], "explanation": "130 and 170 billion tonnes are both a few years of current emissions."}, "proReasoning": "Good analysts explain why credible sources differ, then give the point they agree on.", "commonMistake": "Defending one number as the only truth when experts publish a range.", "mentalModel": "Give the range, then the shared conclusion."}, "invest": {"call": {"kind": "theCall", "situation": "You assess a coal plant built to run for 30 more years.", "prompt": "What does a three-year budget signal?", "options": ["Higher odds of tighter rules before payback", "No risk, since budgets are only estimates", "The plant will close next year by law"], "correctIndex": 0, "consequences": ["You price in policy risk over the plant's life.", "Estimates still shape what governments do.", "No law closes it next year; the risk is gradual."], "explanation": "A budget measured in years, against a plant measured in decades, raises policy risk."}, "proReasoning": "Investors compare an asset's life with the carbon budget. Long-lived fossil assets face rising policy risk.", "commonMistake": "Treating a scientific budget as irrelevant to asset value.", "mentalModel": "Compare asset life with budget life."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your climate product works well but takes ten years to reach scale.", "prompt": "What does the budget suggest?", "options": ["Stop, since the budget is already gone", "Find a path to scale much faster", "Ten years is fine for any climate product"], "correctIndex": 1, "consequences": ["Every tonne avoided still limits warming.", "Speed of scaling matters as much as performance.", "The budget may be spent before you scale."], "explanation": "With about three years of 1.5°C budget left, how fast a solution scales matters a lot."}, "proReasoning": "Founders should plan for speed. A slower product still helps, but faster rollout cuts more tonnes in time.", "commonMistake": "Assuming there is time for a slow rollout.", "mentalModel": "Speed of scaling is part of the product."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that only about three years of budget remain.", "prompt": "What does that actually mean?", "options": ["The world ends in three years", "Emissions must stop entirely, starting tomorrow morning", "At today's pace, 1.5°C emissions run out in ~3 years"], "correctIndex": 2, "consequences": ["It is about a temperature limit, not the end of the world.", "It sets a budget, not an overnight stop.", "You read it as a running total, not a doomsday clock."], "explanation": "A carbon budget is a running total. At current emissions, the 1.5°C budget lasts about three years."}, "proReasoning": "Think of it like a bank balance being spent at a known rate.", "commonMistake": "Reading a budget as a doomsday date.", "mentalModel": "A budget is a balance, not a deadline."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:71e6d65e47d9$ml$]::text[]),
($ml$ba3d78e0-1f31-5f64-a285-71cb38da5594$ml$::uuid, $ml$climatetech$ml$, 4, 2, $ml${"id": "climatetech-d4-c2", "title": "Watching the dial climb", "lessonTitle": "The numbers that frame climate risk", "slot": 2, "type": "connect", "brief": {"headline": "CO2 in the air rose 1.8 ppm in a year to a May peak of 432 ppm in 2026. In 2025 it averaged 425.7 ppm, 52% above pre-industrial.", "kicker": "Connect day 1 and day 4: the stock keeps growing.", "fullText": "Day 1 showed the chain: emissions raise the CO2 level, and the CO2 level drives warming. Day 4 shows the pace: fossil emissions hit a record 38.1 billion tonnes in 2025.\n\nThat pace is visible on the dial. CO2 rose 1.8 ppm in a year, reaching a seasonal peak of 432 ppm in May 2026. As long as emissions stay near record levels, the level keeps climbing.", "sources": [{"url": "https://today.ucsd.edu/story/annual-carbon-dioxide-peak-reaches-432-parts-per-million", "label": "UC San Diego, CO2 peak reaches 432 ppm"}, {"url": "https://globalcarbonbudget.org/fossil-fuel-co2-emissions-hit-record-high-in-2025/", "label": "Global Carbon Budget 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["CO2 peaked at 432 ppm in May 2026.", "Record emissions keep pushing the CO2 level up.", "CO2 levels fell in 2026 as emissions hit a record."], "fakeIndex": 2, "explanation": "CO2 rose 1.8 ppm in a year. Record emissions add to the stock, so the level keeps rising."}, "numbers": {"kind": "numberSense", "prompt": "If CO2 kept rising about 1.8 ppm a year from 432, roughly where would it be in 10 years?", "min": 380, "max": 500, "value": 450, "unit": "ppm", "explanation": "432 plus about 18 is roughly 450 ppm. A steady pace adds up quickly."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A data team asks which indicator best shows whether climate action is working globally.", "prompt": "What do you suggest tracking?", "options": ["The yearly rise in CO2 ppm, and if it slows", "The number of climate pledges made", "The count of climate conferences held"], "correctIndex": 0, "consequences": ["A slowing rise would show emissions falling.", "Pledges are promises, not measured results.", "Meetings do not measure the atmosphere."], "explanation": "The CO2 level is measured directly. A slower annual rise would mean emissions are falling."}, "proReasoning": "Pick indicators that measure outcomes, not activity. The ppm curve is the outcome.", "commonMistake": "Tracking inputs like pledges as if they were results.", "mentalModel": "Track outcomes, not announcements."}, "invest": {"call": {"kind": "theCall", "situation": "A fund manager says climate policy is slowing, so carbon risk is falling.", "prompt": "What does the CO2 data suggest?", "options": ["CO2 data has no link to policy", "The stock keeps rising, so pressure keeps building", "Risk is falling now, because CO2 levels are falling"], "correctIndex": 1, "consequences": ["Rising levels drive both damage and future rules.", "Rising CO2 means rising physical and policy pressure.", "CO2 levels are rising, not falling."], "explanation": "CO2 rose 1.8 ppm in a year. Physical risk grows with the stock, whatever politics does this year."}, "proReasoning": "Investors separate the political cycle from the physical trend, which keeps rising.", "commonMistake": "Reading a pause in policy as a fall in risk.", "mentalModel": "Politics cycles; the stock keeps rising."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are building a startup that verifies emission cuts with sensors.", "prompt": "What does the climbing dial say about your market?", "options": ["The market is shrinking as CO2 falls", "Only governments will ever measure CO2", "Demand for proof of real cuts will grow"], "correctIndex": 2, "consequences": ["CO2 is rising, which raises the stakes.", "Companies already report and buy verification.", "As pressure builds, buyers need verified results."], "explanation": "A rising stock keeps pressure on emitters to prove real reductions."}, "proReasoning": "When the outcome keeps worsening, proof of real progress becomes more valuable.", "commonMistake": "Assuming measurement is only a government job.", "mentalModel": "Rising stakes raise the value of proof."}, "curiosity": {"call": {"kind": "theCall", "situation": "You learn CO2 peaks each May and wonder why.", "prompt": "What matters more than the seasonal wiggle?", "options": ["The higher peak each year, from emissions", "The May peak itself, which is random", "The autumn dip, which shows recovery"], "correctIndex": 0, "consequences": ["The year-on-year rise is the human signal.", "The peak is seasonal, but each one is higher.", "The dip comes back up higher every year."], "explanation": "Each May peak is higher than the last: 1.8 ppm higher in 2026."}, "proReasoning": "Compare like with like: this May against last May shows the trend.", "commonMistake": "Reading a seasonal dip as progress.", "mentalModel": "Compare peak with peak."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:797b7f00164c$ml$]::text[]),
($ml$0ab030f8-a176-5c9d-9e10-558e92e4aaaf$ml$::uuid, $ml$climatetech$ml$, 4, 3, $ml${"id": "climatetech-d4-c3", "title": "A kiln for thirty years", "lessonTitle": "The numbers that frame climate risk", "slot": 3, "type": "decide", "brief": {"headline": "You run strategy at a cement company. The board wants to approve a new kiln built to run for 30 years. About 170 billion tonnes of 1.5°C budget remain, about four years at 2025 emissions.", "kicker": "Decide how the budget shapes a 30-year bet.", "fullText": "The Global Carbon Budget 2025 calls the 1.5°C budget virtually exhausted: about 170 billion tonnes, or four years at 2025 emissions. Fossil emissions reached a record 38.1 billion tonnes, and land-use emissions added about 4.1 billion tonnes.\n\nEvery tonne emitted now leaves less for later. Your kiln would emit for decades, while the budget is measured in years.", "sources": [{"url": "https://globalcarbonbudget.org/fossil-fuel-co2-emissions-hit-record-high-in-2025/", "label": "Global Carbon Budget 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does this use up the remaining carbon budget or not?", "buckets": ["Uses up budget", "Does not"], "items": [{"text": "A year of fossil fuel emissions", "bucket": 0}, {"text": "CO2 from cutting down forests", "bucket": 0}, {"text": "Exhaust from your new kiln", "bucket": 0}, {"text": "Power from a solar farm", "bucket": 1}, {"text": "CO2 captured and stored underground", "bucket": 1}], "explanation": "Fossil and land-use CO2 spend the budget. Clean power and stored CO2 do not add to it."}, "numbers": {"kind": "numberSense", "prompt": "Fossil emissions were 38.1 billion tonnes and land use 4.1. About how many billion tonnes in total?", "min": 0, "max": 100, "value": 42, "unit": "Gt", "explanation": "About 42 billion tonnes a year, which is why 170 billion tonnes lasts about four years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You present the kiln plan to the board as a junior strategist.", "prompt": "What should your slide stress?", "options": ["The kiln will be banned within four years", "Rules may tighten long before the kiln pays back", "Carbon budgets do not matter to a cement firm"], "correctIndex": 1, "consequences": ["The budget raises risk, it does not set a ban date.", "You link the budget to a real business risk.", "Cement is a large, regulated emitter."], "explanation": "A four-year budget against a 30-year kiln points to rising regulatory risk."}, "proReasoning": "Turn a science number into a business risk the board can weigh. That is the strategist's job.", "commonMistake": "Presenting the budget as a precise ban date.", "mentalModel": "Translate the budget into risk over the asset's life."}, "invest": {"call": {"kind": "theCall", "situation": "You're a shareholder. The company plans the kiln with no plan for its emissions.", "prompt": "What do you ask management?", "options": ["Why not build three kilns instead of one", "Nothing, since cement demand is stable", "How the kiln stays viable as carbon costs rise"], "correctIndex": 2, "consequences": ["More kilns multiply the same risk.", "Stable demand does not protect against carbon costs.", "You test the plan against rising carbon costs."], "explanation": "The budget is nearly spent, so carbon costs are likely to rise over a 30-year life."}, "proReasoning": "Shareholders ask how long-lived assets survive tighter rules. It is a question about future cash flows.", "commonMistake": "Assuming stable demand makes an asset safe.", "mentalModel": "Test long-lived assets against carbon costs."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell carbon capture units for kilns. This company is planning a new one.", "prompt": "When do you pitch?", "options": ["Now, while the kiln is still being designed", "After the kiln is built and running", "Never, since cement firms do not care"], "correctIndex": 0, "consequences": ["Designing it in is cheaper than adding it later.", "A retrofit costs more and may not fit.", "Cement firms face rising carbon costs."], "explanation": "The cheapest moment to plan for capture is before the kiln is built."}, "proReasoning": "Founders sell into the design moment. Big assets are cheapest to change on paper.", "commonMistake": "Waiting until the asset is finished and locked in.", "mentalModel": "Pitch at the design stage."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a budget of four years matters for a kiln.", "prompt": "What is the link?", "options": ["The budget only covers cars", "The kiln would emit long after the budget runs out", "It does not matter, since kilns emit very little"], "correctIndex": 1, "consequences": ["The budget covers all CO2.", "Long-lived assets lock in emissions for decades.", "Cement is one of the biggest industrial emitters."], "explanation": "Every tonne counts against one shared budget, and a kiln emits for decades."}, "proReasoning": "Long-lived machines decide emissions for decades. That is why new builds matter.", "commonMistake": "Thinking the budget only covers some sources.", "mentalModel": "New builds lock in decades of emissions."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:08dc6ce2e425$ml$]::text[]),
($ml$443b22ab-6af7-5245-9910-9f8cbb1e9f34$ml$::uuid, $ml$climatetech$ml$, 5, 1, $ml${"id": "climatetech-d5-c1", "title": "Linking two carbon markets", "lessonTitle": "The rule that prices carbon", "slot": 1, "type": "apply", "brief": {"headline": "On May 19, 2025, the UK and the EU agreed to work toward linking their carbon markets. UK permits were trading near £50 a tonne, EU permits near €70.", "kicker": "Apply the rule: what changes when two carbon prices meet?", "fullText": "In January 2025, a UK allowance cost about £32.57 and an EU allowance about €71.52. After the summit deal, UK prices rose toward £50.\n\nA link would let the two markets act as one, creating what both sides called a level playing field. It would also exempt each side's goods from the other's carbon border charge. The EU border charge starts on January 1, 2026, and the UK's on January 1, 2027.", "sources": [{"url": "https://www.fastmarkets.com/insights/uk-eu-agree-to-work-toward-linking-emissions-trading-systems/", "label": "Fastmarkets, UK and EU agree to work toward linking their ETS"}, {"url": "https://carbonmarketwatch.org/2024/02/29/faq-what-is-the-eu-emissions-trading-system-eu-ets/", "label": "Carbon Market Watch, EU ETS FAQ"}]}, "evidence": {"kind": "faceOff", "prompt": "In January 2025, whose carbon permits were cheaper, even after converting currencies?", "left": {"name": "UK allowances", "note": "About £32.57 a tonne"}, "right": {"name": "EU allowances", "note": "About €71.52 a tonne"}, "correctIndex": 0, "explanation": "UK permits cost well under half the EU price. Linking the markets would pull the two prices together."}, "numbers": {"kind": "numberSense", "prompt": "UK permits rose from about £32.57 in January to about £50 by May. Roughly what percent rise?", "min": 0, "max": 150, "value": 54, "unit": "%", "explanation": "About 54%. The prospect of linking with a pricier market lifted the cheaper one."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A carbon trading desk asks what a UK-EU link would do to the two prices.", "prompt": "What do you expect?", "options": ["They would move toward one shared price", "The UK price would fall further below", "Nothing, since each market stays separate"], "correctIndex": 0, "consequences": ["Linked permits can be traded across, so prices converge.", "The cheaper market tends to rise toward the dearer one.", "Linking is exactly what removes the separation."], "explanation": "If permits trade across both markets, the price gap closes. UK prices already rose on the news."}, "proReasoning": "Traders think in arbitrage: when two markets link, the price gap is the opportunity and it closes.", "commonMistake": "Expecting two linked markets to keep different prices.", "mentalModel": "Linked markets converge on one price."}, "invest": {"call": {"kind": "theCall", "situation": "You own a UK steelmaker that exports to the EU.", "prompt": "What does the link mean for it?", "options": ["A new EU border charge on top", "Higher UK carbon costs, but no EU border charge", "Lower carbon costs and no border charge at all"], "correctIndex": 1, "consequences": ["The link would exempt it from that charge.", "You weigh both effects of the deal.", "UK carbon prices rose on the news."], "explanation": "Linking would lift UK carbon prices but spare UK exports from the EU border charge."}, "proReasoning": "Investors trace a policy through costs and market access. Here one rises and one improves.", "commonMistake": "Seeing only one side of a two-sided policy.", "mentalModel": "Trace both the cost and the access."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build carbon accounting software for UK manufacturers.", "prompt": "What does the link mean for your customers?", "options": ["They will stop caring about carbon once linked", "Their reporting will disappear", "They face EU-level prices, so cuts pay off more"], "correctIndex": 2, "consequences": ["Higher prices make carbon matter more.", "Linked markets still need emissions reporting.", "Higher prices raise the value of every tonne cut."], "explanation": "A higher carbon price makes each avoided tonne worth more, which raises demand for tools that find cuts."}, "proReasoning": "When the price per tonne rises, tools that cut tonnes become easier to sell.", "commonMistake": "Assuming policy changes reduce the need for measurement.", "mentalModel": "A higher price raises the value of cuts."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why two neighbors would link carbon markets.", "prompt": "What is the main benefit?", "options": ["One price avoids border charges between them", "It lets both sides stop cutting emissions", "It makes all permits free"], "correctIndex": 0, "consequences": ["Trade flows without carbon border charges.", "Caps still limit emissions on both sides.", "Permits keep a market price."], "explanation": "A shared carbon price creates a level playing field and removes each side's border charge for the other."}, "proReasoning": "Linking turns two prices into one, so neither side needs to charge the other at the border.", "commonMistake": "Thinking a link weakens the caps.", "mentalModel": "One price, no border charge."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b07a341be120$ml$]::text[]),
($ml$24bb5552-0fb1-5a63-98f9-059d3b8b3dfa$ml$::uuid, $ml$climatetech$ml$, 5, 2, $ml${"id": "climatetech-d5-c2", "title": "A budget with a market", "lessonTitle": "The rule that prices carbon", "slot": 2, "type": "connect", "brief": {"headline": "The EU cap on emissions shrinks 4.3% a year from 2024 to 2027, then 4.4% a year to 2030. It works like a carbon budget, with a price attached.", "kicker": "Connect day 4 and day 5: a cap is a budget you can trade.", "fullText": "Day 4 showed that the global carbon budget is fixed: every tonne emitted leaves less for later. The EU Emissions Trading System applies the same idea to power, heavy industry, aviation and shipping, about 36% of EU emissions.\n\nThe cap limits total emissions, and companies trade allowances of one tonne each. Every year they must surrender allowances equal to their emissions or pay a fine. As the cap shrinks, allowances get scarcer.", "sources": [{"url": "https://carbonmarketwatch.org/2024/02/29/faq-what-is-the-eu-emissions-trading-system-eu-ets/", "label": "Carbon Market Watch, EU ETS FAQ"}, {"url": "https://globalcarbonbudget.org/fossil-fuel-co2-emissions-hit-record-high-in-2025/", "label": "Global Carbon Budget 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put one year of the EU system in order.", "steps": ["The EU sets the cap for the year", "Allowances are auctioned or handed out", "Companies emit and track their tonnes", "Companies buy or sell spare allowances", "Each company surrenders one allowance per tonne"], "explanation": "Cap, allocate, emit, trade, surrender. Next year the cap is lower, so allowances get scarcer."}, "numbers": {"kind": "numberSense", "prompt": "The cap shrinks 4.3% a year from 2024 to 2027. About how much smaller is it after those four years?", "min": 0, "max": 50, "value": 16, "unit": "%", "explanation": "Four cuts of 4.3% compound to about 16%. A budget that shrinks every year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks how a cap-and-trade system resembles a carbon budget.", "prompt": "Which answer connects them?", "options": ["Neither limits total emissions", "Both fix total tonnes; the cap adds a price", "Both set one fixed price for every tonne"], "correctIndex": 1, "consequences": ["Limiting total tonnes is exactly what both do.", "You see the cap as a tradable budget.", "A cap fixes the amount; the market sets the price."], "explanation": "A cap is a budget of tonnes. Trading gives each tonne a price."}, "proReasoning": "Connecting a policy to the science behind it shows you understand why it is designed that way.", "commonMistake": "Confusing a cap with a fixed carbon tax.", "mentalModel": "A cap is a tradable budget."}, "invest": {"call": {"kind": "theCall", "situation": "You model EU carbon prices for the rest of the decade.", "prompt": "What does a shrinking cap imply?", "options": ["Prices must fall now that fewer permits exist", "The cap has no effect on prices", "Allowances get scarcer, pushing prices up over time"], "correctIndex": 2, "consequences": ["Less supply against steady demand raises price.", "Supply of permits is what sets scarcity.", "Scarcer supply tends to raise the price."], "explanation": "A cap cut 4.3% a year means fewer permits each year. Scarcity tends to lift prices."}, "proReasoning": "Investors model supply first. A falling cap is shrinking supply, written into law.", "commonMistake": "Forgetting that the supply of permits is set to fall.", "mentalModel": "Shrinking supply, rising scarcity."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell efficiency upgrades to EU factories in the trading system.", "prompt": "How do you frame your pitch?", "options": ["Each tonne cut is one fewer permit to buy", "Efficiency is good for the planet", "Permits are free, so carbon costs nothing"], "correctIndex": 0, "consequences": ["You speak in the customer's cost terms.", "True, but it does not show the saving.", "Covered firms must surrender one per tonne."], "explanation": "Under the cap, every tonne avoided is an allowance the factory does not have to buy."}, "proReasoning": "Founders turn tonnes into money. Under a cap, each tonne avoided has a market price.", "commonMistake": "Pitching values when the buyer decides on cost.", "mentalModel": "Price each tonne you save."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder how a market can cut emissions if companies can just buy permits.", "prompt": "What's the catch for polluters?", "options": ["Buying permits is always free", "The total permits shrink every year", "Permits never run out"], "correctIndex": 1, "consequences": ["Permits cost money, often tens of euros.", "Buying is possible, but the total keeps falling.", "The cap cuts the supply every year."], "explanation": "Companies can trade, but the cap on the total shrinks each year."}, "proReasoning": "The market decides who cuts; the cap decides how much in total.", "commonMistake": "Thinking trading lets total emissions grow.", "mentalModel": "Trading moves cuts around; the cap sets the total."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8f97ea093a81$ml$]::text[]),
($ml$57f0f792-81c1-5b32-870f-5ab68288bae2$ml$::uuid, $ml$climatetech$ml$, 5, 3, $ml${"id": "climatetech-d5-c3", "title": "Which scope to cut first", "lessonTitle": "The rule that prices carbon", "slot": 3, "type": "decide", "brief": {"headline": "You lead emissions reporting at a European grocery chain. The CEO wants a first reduction target. Companies count emissions in three scopes: their own, their purchased energy, and their value chain.", "kicker": "Decide where the first target should land.", "fullText": "Scope 1 covers direct emissions, such as fuel burned in your own trucks and boilers. Scope 2 covers the electricity and heat you buy. Scope 3 covers your value chain, from the farms that grow your products to customers using them.\n\nScope 3 is the hardest to measure, because the data sits with other companies. The EU carbon market covers about 36% of EU emissions, mostly power and heavy industry.", "sources": [{"url": "https://dart.deloitte.com/USDART/home/publications/deloitte/additional-deloitte-guidance/greenhouse-gas-protocol-reporting-considerations/chapter-3-setting-operational-boundaries/3-2-overview-direct-indirect-emissions", "label": "Deloitte DART, GHG Protocol scopes"}, {"url": "https://carbonmarketwatch.org/2024/02/29/faq-what-is-the-eu-emissions-trading-system-eu-ets/", "label": "Carbon Market Watch, EU ETS FAQ"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which scope does this emission belong to?", "buckets": ["Scope 1", "Scope 2", "Scope 3"], "items": [{"text": "Diesel in your own delivery trucks", "bucket": 0}, {"text": "Gas burned in your warehouse boilers", "bucket": 0}, {"text": "Electricity bought to run your stores", "bucket": 1}, {"text": "Farms that grow the food you sell", "bucket": 2}, {"text": "Packaging made by your suppliers", "bucket": 2}], "explanation": "Your own fuel is Scope 1, bought power is Scope 2, and suppliers' emissions are Scope 3."}, "numbers": {"kind": "numberSense", "prompt": "About what share of EU emissions does the EU carbon market cover?", "min": 0, "max": 100, "value": 36, "unit": "%", "explanation": "About 36%: power, heavy industry, aviation and shipping. A grocery chain sits mostly outside it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In your first month, the CEO asks why Scope 3 numbers are so uncertain.", "prompt": "What do you explain?", "options": ["Scope 3 is small, so nobody bothers measuring it", "Scope 3 is made up by consultants", "The data sits with suppliers and farms, not us"], "correctIndex": 2, "consequences": ["For a grocer, the value chain is usually the largest part.", "It is real emissions, just measured indirectly.", "You name the real reason and the fix: supplier data."], "explanation": "Scope 3 depends on other companies' data, which makes it the hardest scope to measure."}, "proReasoning": "Knowing why Scope 3 is hard is a strong signal in sustainability and finance roles.", "commonMistake": "Treating Scope 3 as optional because it is hard to measure.", "mentalModel": "Scope 3 is hard because the data is elsewhere."}, "invest": {"call": {"kind": "theCall", "situation": "You compare two grocers. One reports only Scope 1 and 2.", "prompt": "What is missing from its picture?", "options": ["Most of a grocer's emissions, in the supply chain", "Nothing, since Scope 3 is not real emissions", "Only a tiny rounding error"], "correctIndex": 0, "consequences": ["You see the gap where the biggest risk sits.", "Value chain emissions are real and often largest.", "For food retail it is far more than a rounding error."], "explanation": "A grocer's value chain, from farms to packaging, is where most of its emissions sit."}, "proReasoning": "Investors ask what is left out. For retailers, the value chain is the largest exposure.", "commonMistake": "Comparing companies that report different scopes as if they were equal.", "mentalModel": "Check which scopes are left out."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're a founder. This grocer is a target customer.", "prompt": "Which product solves their hardest problem?", "options": ["A guide to what Scope 1 means", "Collecting emissions data from their suppliers", "A smart meter for the lights in their own stores"], "correctIndex": 1, "consequences": ["They already know the definitions.", "You solve the scope they cannot measure alone.", "Store electricity is the easy part to measure."], "explanation": "Scope 3 data sits with suppliers. Gathering it is the hard, valuable job."}, "proReasoning": "Founders target the hardest step in a customer's process. For most firms that is Scope 3 data.", "commonMistake": "Building for the easy part buyers already handle.", "mentalModel": "Solve the hardest step."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why your grocery store would count the farms' emissions.", "prompt": "Why include them?", "options": ["Farms pay the grocer to count them", "It is required for every shop by law", "Selling food drives those farm emissions"], "correctIndex": 2, "consequences": ["No payment is involved in reporting.", "Rules vary, and many shops report voluntarily.", "The value chain exists because of what the store sells."], "explanation": "Scope 3 counts emissions your business causes through what it buys and sells."}, "proReasoning": "Scope 3 follows responsibility along the chain, not just ownership.", "commonMistake": "Thinking a company only causes what it burns itself.", "mentalModel": "Count what your business causes."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e1e70d6a30db$ml$]::text[]),
($ml$494309bb-68d6-57a3-b9ab-47fd0c7afcf5$ml$::uuid, $ml$climatetech$ml$, 6, 1, $ml${"id": "climatetech-d6-c1", "title": "The bill for a burned city", "lessonTitle": "When climate risk hits the balance sheet", "slot": 1, "type": "apply", "brief": {"headline": "In May 2025, California approved a 17% emergency rate rise for State Farm's roughly one million homeowner policies, after it paid over $3.5 billion in Los Angeles fire claims.", "kicker": "Apply the rule: how does climate risk reach your premium?", "fullText": "State Farm first asked for 22% and revised it to 17%. Rental owners faced 38% and tenants 15%. By mid-May the insurer had paid more than $3.51 billion on the January fires, with more than 12,600 claims still open.\n\nState Farm General had been downgraded and its surplus had fallen by $5 billion over a decade. Its parent added a $400 million cash infusion. The fires caused about $40 billion of insured losses in total.", "sources": [{"url": "https://insurancenewsnet.com/oarticle/california-approves-state-farms-request-for-17-premium-increase-for-homeowners", "label": "InsuranceNewsNet, California approves State Farm's 17% increase"}, {"url": "https://www.insurancebusinessmag.com/reinsurance/news/breaking-news/la-wildfires-40-billion-insured-losses-make-it-2025s-costliest-catastrophe--howden-re-561886.aspx", "label": "Insurance Business, LA wildfires were 2025's costliest catastrophe"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow the fire to the premium.", "steps": ["Wildfires destroy thousands of homes", "State Farm pays over $3.5 billion in claims", "Its capital cushion shrinks", "It asks regulators for an emergency rate rise", "Homeowners pay about 17% more"], "explanation": "Climate losses become claims, claims drain capital, and capital needs become higher premiums."}, "numbers": {"kind": "numberSense", "prompt": "State Farm asked for 22%. What homeowner rate rise did California approve?", "min": 0, "max": 50, "value": 17, "unit": "%", "explanation": "17%, after the insurer revised its request at a hearing."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An insurer hiring climate analysts asks what made this rate rise necessary.", "prompt": "What is the core reason?", "options": ["Wildfires had no effect on claims", "Losses drained capital faster than premiums refilled it", "Regulators simply wanted higher prices across the state"], "correctIndex": 1, "consequences": ["Fire claims were over $3.5 billion.", "You link losses, capital and pricing.", "Regulators approved it after a hearing on the numbers."], "explanation": "Billions in fire claims and a shrinking surplus forced the insurer to raise prices."}, "proReasoning": "Climate risk analysts connect losses to capital. That is how risk becomes a price.", "commonMistake": "Treating a premium rise as unrelated to the losses behind it.", "mentalModel": "Losses drain capital; capital sets price."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a property insurer with heavy exposure in fire zones.", "prompt": "What do you watch?", "options": ["Only last year's profits", "The number of new policies it sells", "Whether rates can rise as fast as losses"], "correctIndex": 2, "consequences": ["One year's profit hides a growing risk.", "More policies in fire zones can mean more risk.", "You track the race between losses and pricing."], "explanation": "State Farm needed an emergency rise after losses outpaced its prices."}, "proReasoning": "Investors watch whether an insurer can reprice as fast as its losses grow.", "commonMistake": "Judging an insurer by growth in policies sold.", "mentalModel": "Watch pricing against losses."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup hardens homes against wildfire.", "prompt": "Who might pay to help you grow?", "options": ["Insurers who pay out less on hardened homes", "Only homeowners, out of their own pocket", "Nobody, since fires are unpredictable"], "correctIndex": 0, "consequences": ["Insurers save on claims, so they have a reason to pay.", "Insurers also gain from fewer losses.", "Risk can be reduced even if fires are not predictable."], "explanation": "An insurer that paid over $3.5 billion on one fire season gains from fewer losses."}, "proReasoning": "Founders find the party that saves money when the risk falls. Here, that is the insurer.", "commonMistake": "Pitching only the end customer when a bigger payer benefits.", "mentalModel": "Find who saves when risk falls."}, "curiosity": {"call": {"kind": "theCall", "situation": "You don't live in California and wonder why this matters to you.", "prompt": "How does it reach other places?", "options": ["It lowers insurance prices elsewhere", "Big losses push up insurance prices widely", "It only affects Los Angeles"], "correctIndex": 1, "consequences": ["Losses raise prices, they do not lower them.", "Insurers and reinsurers spread costs across markets.", "Insurers price risk across their whole business."], "explanation": "Insured disaster losses topped $100 billion a year twice running, which pushes prices up broadly."}, "proReasoning": "Insurance links distant disasters to your premium through shared capital.", "commonMistake": "Thinking a local disaster stays local.", "mentalModel": "Shared capital spreads the cost."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:cebfafd5bc86$ml$]::text[]),
($ml$45ee1a30-c757-571b-9cc7-052becf236dd$ml$::uuid, $ml$climatetech$ml$, 6, 2, $ml${"id": "climatetech-d6-c2", "title": "Hot years, big bills", "lessonTitle": "When climate risk hits the balance sheet", "slot": 2, "type": "connect", "brief": {"headline": "The ten warmest years on record were 2015 to 2024. In 2025, natural disasters cost insurers about $108 billion, the second straight year above $100 billion.", "kicker": "Connect day 1 and day 6: rising heat shows up in claims.", "fullText": "Day 1 showed the trend: 2024 was about 1.55°C above pre-industrial, and the last ten years were the ten warmest. Day 6 shows where it lands for business.\n\nThe January 2025 Los Angeles wildfires caused about $40 billion in insured losses and about $53 billion overall. Insured losses are what insurers pay; the rest is damage nobody covered.", "sources": [{"url": "https://wmo.int/news/media-centre/wmo-confirms-2024-warmest-year-record-about-155degc-above-pre-industrial-level", "label": "WMO, 2024 warmest year on record"}, {"url": "https://www.insurancebusinessmag.com/reinsurance/news/breaking-news/la-wildfires-40-billion-insured-losses-make-it-2025s-costliest-catastrophe--howden-re-561886.aspx", "label": "Insurance Business, LA wildfires were 2025's costliest catastrophe"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Insured losses were $40 billion, overall losses $53 billion. Who carried the gap?", "options": ["The insurers, a second time", "Nobody, the two figures are the same loss", "Owners and others without enough insurance"], "correctIndex": 2, "explanation": "Insured losses are what insurers pay. The other $13 billion fell on people and firms without cover."}, "numbers": {"kind": "numberSense", "prompt": "Insured losses were $40 billion of $53 billion overall. About what share was insured?", "min": 0, "max": 100, "value": 75, "unit": "%", "explanation": "About 75%. A quarter of the damage was not covered by insurance."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A reinsurer asks what links rising temperatures to its business.", "prompt": "What do you answer?", "options": ["Temperatures do not affect insurance", "Hot years lower claims by reducing storms", "More extreme events mean larger insured losses"], "correctIndex": 2, "consequences": ["Losses above $100 billion twice running suggest otherwise.", "Losses have risen, not fallen.", "You connect the trend to the loss record."], "explanation": "Ten record warm years and two years above $100 billion in insured losses sit side by side."}, "proReasoning": "Linking the science trend to the loss data is the core skill in climate risk roles.", "commonMistake": "Discussing temperature without the losses it drives.", "mentalModel": "Pair the trend with the losses."}, "invest": {"call": {"kind": "theCall", "situation": "You look at a homebuilder selling in fire-prone areas.", "prompt": "What risk does the $13 billion gap reveal?", "options": ["Uninsured losses can fall on owners and lenders", "There is no real risk as long as homes are insured", "Gaps only matter to insurers"], "correctIndex": 0, "consequences": ["You see that not all damage is covered.", "A quarter of the LA damage was uninsured.", "Uninsured losses fall on others."], "explanation": "About $13 billion of LA damage was not insured, so others carried it."}, "proReasoning": "Investors check the protection gap, the losses that land on owners and lenders.", "commonMistake": "Assuming insurance absorbs every loss.", "mentalModel": "Check the protection gap."}, "build_startup": {"call": {"kind": "theCall", "situation": "You see that a quarter of disaster damage goes uninsured.", "prompt": "Which startup idea targets that gap?", "options": ["Selling more insurance to the already insured", "Cheaper cover for people insurers turn down", "A weather app with nicer graphics"], "correctIndex": 1, "consequences": ["The insured are already protected.", "You go where losses fall with no protection.", "Forecasts help, but do not cover losses."], "explanation": "The gap between $53 billion and $40 billion is damage nobody covered."}, "proReasoning": "A protection gap is an unserved market. Founders look for losses no one covers.", "commonMistake": "Building for customers who are already served.", "mentalModel": "Serve the unprotected."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear disasters cost insurers over $100 billion again in 2025.", "prompt": "Is that a one-off?", "options": ["Yes, it never happened before", "It happens every few decades", "No, it was the second year in a row"], "correctIndex": 2, "consequences": ["2024 was also above $100 billion.", "It is now happening year after year.", "Two years running points to a trend."], "explanation": "Insured disaster losses topped $100 billion in both 2024 and 2025."}, "proReasoning": "One big year is news. Two in a row is a pattern worth watching.", "commonMistake": "Treating each record as a fluke.", "mentalModel": "Look for repeats."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0843cbe7e290$ml$]::text[]),
($ml$becf7c73-e83b-5f08-b094-7c0423b5b427$ml$::uuid, $ml$climatetech$ml$, 6, 3, $ml${"id": "climatetech-d6-c3", "title": "Rebuild faster or rebuild safer", "lessonTitle": "When climate risk hits the balance sheet", "slot": 3, "type": "decide", "brief": {"headline": "You lead rebuilding for a city hit by wildfire. More than 15,000 structures were damaged or destroyed, and a year on, only about 16% of rebuild permits have been issued.", "kicker": "Decide how to speed up rebuilding without rebuilding the risk.", "fullText": "This is the Los Angeles situation after January 2025. The fires caused about $40 billion in insured losses and $53 billion overall, the costliest natural disaster of the year.\n\nResidents want to come home. Insurers watch whether rebuilt homes will be safer, because that shapes whether they keep offering cover. You can fast-track permits, require fire-resistant materials, or both.", "sources": [{"url": "https://www.insurancebusinessmag.com/reinsurance/news/breaking-news/la-wildfires-40-billion-insured-losses-make-it-2025s-costliest-catastrophe--howden-re-561886.aspx", "label": "Insurance Business, LA wildfires were 2025's costliest catastrophe"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["More than 15,000 structures were damaged or destroyed.", "About 16% of rebuild permits were issued after a year.", "Insurers ignore how homes are rebuilt."], "fakeIndex": 2, "explanation": "Insurers price risk by location and building features. Safer rebuilds help keep cover available."}, "numbers": {"kind": "numberSense", "prompt": "16% of permits for about 15,000 structures. Roughly how many thousand is that?", "min": 0, "max": 15, "value": 2.4, "unit": "K", "explanation": "About 2,400. Most owners were still waiting a year later."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're on the city's recovery team, asked to design the permit rules.", "prompt": "What do you recommend?", "options": ["Fast-track permits for fire-resistant rebuilds", "Approve anything to move fastest", "Pause all rebuilding until the risk is zero"], "correctIndex": 0, "consequences": ["Speed and safety move together.", "Rebuilding the same risk invites the next loss.", "Risk is never zero, and residents can't wait forever."], "explanation": "A fast lane for safer homes speeds recovery and keeps homes insurable."}, "proReasoning": "Good policy designers find options that serve two goals at once.", "commonMistake": "Trading safety away for speed, or speed for impossible safety.", "mentalModel": "Reward the safer choice with speed."}, "invest": {"call": {"kind": "theCall", "situation": "You lend to homeowners rebuilding in the burn zone.", "prompt": "What reduces your risk most?", "options": ["Ignoring the fire history", "Rebuilds that meet fire-resistant standards", "Lending faster than the other banks in town"], "correctIndex": 1, "consequences": ["History is the best guide to future losses.", "Safer homes keep insurance and value.", "Speed adds volume, not safety."], "explanation": "Homes that stay insurable protect the loan. Insurers watch how homes are rebuilt."}, "proReasoning": "Lenders depend on insurance. Rebuild standards decide whether cover stays available.", "commonMistake": "Lending as if the fire risk vanished with the fire.", "mentalModel": "Insurable homes protect the loan."}, "build_startup": {"call": {"kind": "theCall", "situation": "You make fire-resistant building panels.", "prompt": "What is your best opening?", "options": ["Wait until owners find you on their own", "Sell only outside fire zones", "Partner with the city on a permit fast lane"], "correctIndex": 2, "consequences": ["Owners are deciding now, under pressure.", "Fire zones are where your product matters most.", "Policy creates demand right when owners decide."], "explanation": "With most rebuilds still ahead, a fast lane for safer materials puts you in every decision."}, "proReasoning": "Founders who line up with policy reach customers at the moment they choose.", "commonMistake": "Waiting for demand when policy could create it.", "mentalModel": "Get into the decision moment."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why rebuilding takes so long after a fire.", "prompt": "What slows it down?", "options": ["Permits, insurance and safety rules take time", "Nobody wants to rebuild", "Rebuilding is banned for years after big fires"], "correctIndex": 0, "consequences": ["Each step needs approvals and money.", "Residents want to return.", "Rebuilding is allowed; it is slow."], "explanation": "A year on, only about 16% of rebuild permits had been issued in Los Angeles."}, "proReasoning": "Recovery runs on paperwork and money as much as on builders.", "commonMistake": "Thinking rebuilding is only a construction problem.", "mentalModel": "Recovery runs on permits and payouts."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6908e6e6ccda$ml$]::text[]),
($ml$383c388d-b7dd-53e2-bc72-25b7a186325e$ml$::uuid, $ml$climatetech$ml$, 7, 1, $ml${"id": "climatetech-d7-c1", "title": "Clean power passes 40%", "lessonTitle": "Where emissions come from", "slot": 1, "type": "apply", "brief": {"headline": "Clean sources made 40.9% of the world's electricity in 2024, Ember found. Yet power sector CO2 still rose 1.6% to a record 14.6 billion tonnes.", "kicker": "Apply the rule: why the biggest sector still grew.", "fullText": "Solar generation rose 29%, adding 474 TWh, more than any other source, and passed 2,000 TWh. Clean power's share rose from 39.4% to 40.9%.\n\nBut electricity demand grew 4.0%, against 2.6% the year before. Heatwaves drove more cooling, adding about 0.7% to global demand. Fossil generation rose 1.4%. Without the hotter weather, Ember says it would have risen only 0.2%.", "sources": [{"url": "https://ember-energy.org/latest-insights/global-electricity-review-2025/executive-summary", "label": "Ember, Global Electricity Review 2025"}, {"url": "https://www.wri.org/index%2Ephp/insights/4-charts-explain-greenhouse-gas-emissions-countries-and-sectors", "label": "WRI, 4 charts explain greenhouse gas emissions by countries and sectors"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Clean power reached a record share. Why did power emissions still rise?", "options": ["Heatwaves pushed demand up faster than clean power grew", "Solar output fell during the year", "Clean power plants count as an emission source too"], "correctIndex": 0, "explanation": "Demand grew 4.0%, partly from cooling in heatwaves, so fossil generation still rose 1.4%."}, "numbers": {"kind": "numberSense", "prompt": "To the nearest percent, what share of global electricity came from clean sources in 2024?", "min": 0, "max": 100, "value": 41, "unit": "%", "explanation": "About 41% (40.9%), up from 39.4% in 2023."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A power analytics firm asks why emissions rose in a record year for clean power.", "prompt": "What do you answer?", "options": ["The clean power figures were overstated by Ember", "Clean power makes grids burn more coal", "Demand outgrew clean supply, partly from heat"], "correctIndex": 2, "consequences": ["Ember is a widely used, data-based source.", "Clean power displaces fossil output, it does not add to it.", "You explain the race between demand and clean supply."], "explanation": "Clean power grew fast, but demand grew 4.0%, so fossil generation still rose."}, "proReasoning": "Analysts look at supply and demand together. A share can rise while the total from fossil still grows.", "commonMistake": "Assuming a rising clean share means falling emissions.", "mentalModel": "Check demand before judging supply."}, "invest": {"call": {"kind": "theCall", "situation": "You weigh a gas power plant owner. Demand jumped 4.0% in 2024.", "prompt": "What should worry you longer term?", "options": ["Solar adds the most new power every year", "Demand growth will make gas grow for ever", "Nothing, since fossil generation rose"], "correctIndex": 0, "consequences": ["You see the source winning new demand.", "Solar took the largest share of the growth.", "One year of growth hides the long trend."], "explanation": "Solar added 474 TWh, more than any other source. Over time it takes more of each year's growth."}, "proReasoning": "Investors ask who wins the growth, not just whether demand grows.", "commonMistake": "Reading one strong year for fossil output as a lasting trend.", "mentalModel": "Ask who wins the new demand."}, "build_startup": {"call": {"kind": "theCall", "situation": "You learn heat-driven cooling added 0.7% to world power demand.", "prompt": "What startup idea does that point to?", "options": ["Heaters for homes in warming regions", "More efficient cooling for hot cities", "A new coal plant design for summer"], "correctIndex": 1, "consequences": ["The surge came from cooling, not heating.", "You attack the demand that pushed emissions up.", "Coal raises emissions further."], "explanation": "Heatwaves raised cooling demand. Efficient cooling cuts that growth at the source."}, "proReasoning": "Founders look at what drove a number up. Here, cooling in heatwaves.", "commonMistake": "Building supply when the problem is a demand spike.", "mentalModel": "Attack what drove the rise."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that clean power passed 40% but emissions hit a record.", "prompt": "How can both be true?", "options": ["One of the two numbers is fake", "Clean power secretly produces a lot of CO2 too", "We used more power overall, so fossil grew too"], "correctIndex": 2, "consequences": ["Both come from the same Ember review.", "Solar and wind do not burn fuel.", "A larger pie lets fossil grow even as its share falls."], "explanation": "Total demand grew 4.0%, so fossil generation rose even as clean power gained share."}, "proReasoning": "Shares and totals tell different stories. Check both.", "commonMistake": "Thinking a bigger share means a smaller total.", "mentalModel": "Share is not total."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ef7900d85b2d$ml$]::text[]),
($ml$23bfb011-f0b5-524b-af1f-ae8dcc8799a7$ml$::uuid, $ml$climatetech$ml$, 7, 2, $ml${"id": "climatetech-d7-c2", "title": "Money meets the biggest slice", "lessonTitle": "Where emissions come from", "slot": 2, "type": "connect", "brief": {"headline": "Electricity and heat produce about 33.6% of global greenhouse gas emissions, the largest single sector. Solar, at about $450 billion, was the largest single energy investment in 2025.", "kicker": "Connect day 2 and day 7: money is chasing the biggest slice.", "fullText": "WRI's analysis puts energy use at about 76.7% of emissions: electricity and heat 33.6%, transport 14.3%, manufacturing and construction 12.2% and buildings 6.3%. Agriculture adds 12.3%.\n\nDay 2 showed where money goes: $2.2 trillion into clean energy in 2025, with solar the largest single category. Most of that money cleans up the power sector, the biggest slice of emissions.", "sources": [{"url": "https://www.wri.org/index%2Ephp/insights/4-charts-explain-greenhouse-gas-emissions-countries-and-sectors", "label": "WRI, 4 charts explain greenhouse gas emissions by countries and sectors"}, {"url": "https://sustainabilitymag.com/articles/iea-report-2025-clean-energy-investment-to-reach-us-2-2tn", "label": "Sustainability Magazine on IEA World Energy Investment 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Electricity and heat are the largest emitting sector.", "Solar was the largest single energy investment in 2025.", "Transport emits more than electricity and heat."], "fakeIndex": 2, "explanation": "Transport is about 14.3%, well below electricity and heat at 33.6%."}, "numbers": {"kind": "numberSense", "prompt": "Electricity and heat are 33.6% and transport 14.3%. Together, about what share?", "min": 0, "max": 80, "value": 48, "unit": "%", "explanation": "About 48%, nearly half of global emissions in two sectors."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You want a climate career with the most room to cut emissions.", "prompt": "Which area does the data favor?", "options": ["Power and heat, about a third of emissions", "Waste, at about 3.8%, the smallest slice", "Any sector, since all slices are equal"], "correctIndex": 0, "consequences": ["You go where the most tonnes are.", "Waste matters, but it is the smallest slice.", "Slices differ widely in size."], "explanation": "Electricity and heat are about 33.6%, the biggest slice of emissions."}, "proReasoning": "Picking a sector by its share of emissions shows you think about impact.", "commonMistake": "Choosing a field without knowing its size.", "mentalModel": "Know the size of your slice."}, "invest": {"call": {"kind": "theCall", "situation": "You compare a transport fund and a power fund.", "prompt": "What does the sector map tell you?", "options": ["The two slices are about the same size", "Power is the larger emissions slice by far", "Transport emits more than power does"], "correctIndex": 1, "consequences": ["Power is more than twice as large.", "You compare the size of each opportunity.", "Transport is about 14.3%, power 33.6%."], "explanation": "Electricity and heat are 33.6%, transport 14.3%."}, "proReasoning": "Investors size opportunities by the emissions each sector must cut.", "commonMistake": "Treating sectors as equal opportunities.", "mentalModel": "Size the slice first."}, "build_startup": {"call": {"kind": "theCall", "situation": "Solar already draws the most money. You want to help clean up power.", "prompt": "Where is there room for a new startup?", "options": ["A new solar panel brand in a crowded field", "Nowhere, since solar has the money", "The grid and storage that solar depends on"], "correctIndex": 2, "consequences": ["Panels are where competition is fiercest.", "Big money creates needs around it.", "You serve the bottleneck next to the flood of money."], "explanation": "Solar money flows into the biggest slice. The tools around it, like grids and storage, get pulled along."}, "proReasoning": "Where money floods in, founders look for the bottlenecks next to it.", "commonMistake": "Joining the most crowded category instead of serving it.", "mentalModel": "Serve the flood, do not join it."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why so much climate news is about electricity.", "prompt": "Why is power the focus?", "options": ["It is the biggest emitting sector", "It is the smallest and easiest sector", "Power plants do not emit at all"], "correctIndex": 0, "consequences": ["About a third of emissions come from it.", "It is the largest, not the smallest.", "Fossil power plants emit a lot."], "explanation": "Electricity and heat are about 33.6% of global emissions."}, "proReasoning": "News and money follow the biggest slice. Power is it.", "commonMistake": "Thinking climate is mainly about cars.", "mentalModel": "Follow the biggest slice."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f65fdf5ca112$ml$]::text[]),
($ml$d19ce0d6-0f21-5982-a985-56e71124befd$ml$::uuid, $ml$climatetech$ml$, 7, 3, $ml${"id": "climatetech-d7-c3", "title": "Three tracks for an incubator", "lessonTitle": "Where emissions come from", "slot": 3, "type": "decide", "brief": {"headline": "You run a climate incubator and can fund three sector tracks. Energy use makes about 76.7% of emissions; agriculture 12.3%, industrial processes 6.2% and waste 3.8%.", "kicker": "Decide which sectors get your three tracks.", "fullText": "Within energy, electricity and heat are 33.6%, transport 14.3%, manufacturing and construction 12.2% and buildings 6.3%. Outside energy, agriculture emits through livestock, soils and rice, and industrial processes like cement release gases chemically.\n\nGlobal emissions grew 50% from 1990 to 2023. Your board wants the three tracks to cover as much of that as possible.", "sources": [{"url": "https://www.wri.org/index%2Ephp/insights/4-charts-explain-greenhouse-gas-emissions-countries-and-sectors", "label": "WRI, 4 charts explain greenhouse gas emissions by countries and sectors"}]}, "evidence": {"kind": "faceOff", "prompt": "Which emits more worldwide?", "left": {"name": "Transport", "note": "Cars, trucks, ships and planes"}, "right": {"name": "Agriculture", "note": "Livestock, soils and rice"}, "correctIndex": 0, "explanation": "Transport is about 14.3% and agriculture about 12.3%. Close, but transport is larger."}, "numbers": {"kind": "numberSense", "prompt": "Energy use is about 76.7% of emissions. About what share comes from everything else?", "min": 0, "max": 100, "value": 23, "unit": "%", "explanation": "About 23%: agriculture, industrial processes and waste."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the incubator's analyst. The board asks which three tracks cover the most emissions.", "prompt": "What do you propose?", "options": ["Three tracks all inside buildings", "Power and heat, transport, and agriculture", "Waste, industrial processes and buildings"], "correctIndex": 1, "consequences": ["Buildings are only about 6.3%.", "Those three cover about 60% of emissions.", "Those are the three smallest slices."], "explanation": "Electricity and heat 33.6%, transport 14.3% and agriculture 12.3% add up to about 60%."}, "proReasoning": "Back a recommendation with the numbers it covers. \"About 60% of emissions\" wins the room.", "commonMistake": "Picking tracks by what is fashionable, not by size.", "mentalModel": "Show the share your plan covers."}, "invest": {"call": {"kind": "theCall", "situation": "A donor offers to fund one more track, but only in waste.", "prompt": "How do you weigh it?", "options": ["Reject it outright, since waste is only 3.8%", "Make it the biggest track of all", "Small slice, but worth it if cuts are cheap"], "correctIndex": 2, "consequences": ["Small slices can still offer cheap cuts.", "It is the smallest slice of emissions.", "You weigh size against cost per tonne cut."], "explanation": "Waste is 3.8% of emissions. Its value depends on how cheaply tonnes can be cut there."}, "proReasoning": "Investors weigh both size and cost per tonne. A small slice with cheap cuts can still pay.", "commonMistake": "Rejecting a sector on size alone, or overweighting it.", "mentalModel": "Weigh size against cost per tonne."}, "build_startup": {"call": {"kind": "theCall", "situation": "A founder pitches a tool for rice farms. Agriculture is about 12.3% of emissions.", "prompt": "What is your view?", "options": ["Agriculture is as big as transport; worth a look", "Farming emissions are far too small to matter", "Only energy startups deserve funding"], "correctIndex": 0, "consequences": ["You see a slice nearly as big as transport.", "At 12.3%, agriculture is a major slice.", "About 23% of emissions sit outside energy."], "explanation": "Agriculture, at 12.3%, is about as large as transport at 14.3%."}, "proReasoning": "Founders outside energy can still target a large slice. Agriculture is one.", "commonMistake": "Assuming climate means energy only.", "mentalModel": "Look beyond energy."}, "curiosity": {"call": {"kind": "theCall", "situation": "You are surprised that farming emits as much as it does.", "prompt": "Where do farm emissions come from?", "options": ["Only food packaging", "Livestock, soils and rice fields", "Only the fuel burned by tractors"], "correctIndex": 1, "consequences": ["Packaging is counted elsewhere.", "Most farm emissions are not from fuel.", "Tractor fuel is a small part."], "explanation": "Agriculture emits through livestock, soils and rice, about 12.3% of the total."}, "proReasoning": "Some emissions come from biology, not burning. Farming is the big example.", "commonMistake": "Assuming all emissions come from burning fuel.", "mentalModel": "Not all emissions come from fuel."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2d2efa0a3d3d$ml$]::text[]),
($ml$301e058e-4ff9-5a03-9e79-cbce7c730818$ml$::uuid, $ml$climatetech$ml$, 8, 1, $ml${"id": "climatetech-d8-c1", "title": "Europe's methane test for imports", "lessonTitle": "The gas that is worth catching", "slot": 1, "type": "apply", "brief": {"headline": "EU rules require gas, oil and coal importers to prove methane monitoring as strict as Europe's, then meet methane limits. In October 2026, the Commission proposed delaying each step by a year.", "kicker": "Apply the rule: who pays to catch leaked gas?", "fullText": "Under the EU methane regulation, importers were to show equivalent monitoring from 2027, report methane intensity from 2028 and meet maximum intensity values from 2030. Refusing to provide data can cost up to 20% of annual turnover.\n\nThe US is Europe's largest LNG supplier, and its exporters often lack data from the producers. On October 14, 2026, the Commission proposed pushing each deadline back a year, and Parliament backed a longer delay.", "sources": [{"url": "https://intellinews.com/what-do-eu-methane-rules-mean-for-global-gas-suppliers-324192", "label": "bne IntelliNews, what EU methane rules mean for gas suppliers"}, {"url": "https://www.globalelr.com/2026/10/european-commission-proposes-targeted-delays-to-eu-methane-regulation-requirements/", "label": "Global Environmental Law Review, Commission proposes methane rule delays"}, {"url": "https://airqualitynews.com/headlines/methane-emissions-much-higher-than-they-need-to-be-says-iea/", "label": "Air Quality News, IEA Global Methane Tracker 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the original methane rule timeline for importers in order.", "steps": ["The EU agrees its methane regulation", "Importers must prove equivalent monitoring", "Importers report the methane intensity of supplies", "Maximum methane intensity limits apply", "The Commission proposes a one-year delay"], "explanation": "Monitoring, then reporting, then limits. In October 2026 the Commission proposed moving each step back."}, "numbers": {"kind": "numberSense", "prompt": "Refusing to give methane data can cost up to what share of annual turnover?", "min": 0, "max": 100, "value": 20, "unit": "%", "explanation": "Up to 20% of annual turnover, a penalty large enough to force data sharing."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A US LNG exporter is hiring. They ask what the EU rule means for their sales team.", "prompt": "What is the core challenge?", "options": ["Getting methane data from the gas producers", "Lowering the price of LNG cargoes to Europe", "Shipping cargoes to Europe faster"], "correctIndex": 0, "consequences": ["You name the data gap the rule exposes.", "Price does not satisfy a data rule.", "Speed does not prove low methane."], "explanation": "Exporters often do not produce the gas, so they lack the methane data EU buyers will need."}, "proReasoning": "Knowing where the data sits in a supply chain is valuable in any compliance role.", "commonMistake": "Treating a data rule as a pricing problem.", "mentalModel": "Find who holds the data."}, "invest": {"call": {"kind": "theCall", "situation": "You compare a Qatari and a US gas exporter selling to Europe.", "prompt": "Who finds the rule easier?", "options": ["Neither, the rule treats them the same", "Qatar, with fewer, larger producers", "The US, with many small producers"], "correctIndex": 1, "consequences": ["Supply chain shape changes the burden.", "Concentrated supply makes data easier to gather.", "Many producers make data harder to trace."], "explanation": "Requirements are easier where production is concentrated, like Qatar, than in fragmented US supply."}, "proReasoning": "Investors read a rule through each supplier's structure. Simple chains comply more cheaply.", "commonMistake": "Assuming the same rule costs every supplier the same.", "mentalModel": "Rules weigh on fragmented chains more."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build satellite methane detection. The EU just proposed a one-year delay.", "prompt": "What do you tell investors?", "options": ["The market is dead, so you will pivot", "Delays mean the rules will tighten", "Demand slips a year, but the need remains"], "correctIndex": 2, "consequences": ["A delay is not a repeal.", "A delay pushes rules back, it does not tighten them.", "You stay honest about timing and the need."], "explanation": "The proposal moves deadlines back a year. The monitoring need is still in the law."}, "proReasoning": "Founders selling into regulation plan for delays. A slipped deadline is a timing risk, not the end.", "commonMistake": "Betting a company on one regulatory date.", "mentalModel": "Plan for regulatory delays."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why Europe cares about methane in gas made elsewhere.", "prompt": "Why include imports?", "options": ["Much of its gas is made abroad and leaks there", "Europe produces all its own gas", "Methane only matters if it leaks inside Europe"], "correctIndex": 0, "consequences": ["Leaks abroad still warm the planet.", "Europe imports much of its gas.", "Methane warms the whole world."], "explanation": "Methane leaked where the gas is produced warms the planet just the same."}, "proReasoning": "Emissions do not stop at borders. Buyers can push standards up the chain.", "commonMistake": "Thinking only domestic emissions count.", "mentalModel": "Buyers can push standards upstream."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4d0adaedc99f$ml$]::text[]),
($ml$c54dfaef-af8c-59b1-a553-d7f8cf29ff0b$ml$::uuid, $ml$climatetech$ml$, 8, 2, $ml${"id": "climatetech-d8-c2", "title": "A cut that pays twice", "lessonTitle": "The gas that is worth catching", "slot": 2, "type": "connect", "brief": {"headline": "The IEA says 70% of energy sector methane could be prevented with existing technology, and much of the captured gas can be sold. Where carbon has a price, cutting emissions saves money too.", "kicker": "Connect day 5 and day 8: some cuts pay back twice.", "fullText": "The fossil fuel industry emits over 120 million tonnes of methane a year, about a third of human-caused methane. Leaked methane is gas a company could have sold.\n\nDay 5 showed that when carbon has a price, cutting emissions becomes a business decision. A methane leak combines both: fixing it saves product to sell, and where emissions are priced, it also avoids a carbon cost.", "sources": [{"url": "https://airqualitynews.com/headlines/methane-emissions-much-higher-than-they-need-to-be-says-iea/", "label": "Air Quality News, IEA Global Methane Tracker 2025"}, {"url": "https://carbonmarketwatch.org/2024/02/29/faq-what-is-the-eu-emissions-trading-system-eu-ets/", "label": "Carbon Market Watch, EU ETS FAQ"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why can fixing a methane leak pay for itself?", "options": ["The saved gas is product the company can sell", "Methane has no climate effect at all", "Leaks are fixed for free by national regulators"], "correctIndex": 0, "explanation": "Leaked methane is lost natural gas. Capturing it means more gas to sell."}, "numbers": {"kind": "numberSense", "prompt": "The industry emits about 120 million tonnes, and 70% is preventable. About how many million tonnes?", "min": 0, "max": 120, "value": 84, "unit": "Mt", "explanation": "About 84 million tonnes a year could be prevented with existing technology."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An oil company interviewer asks where you would start cutting emissions.", "prompt": "What is the strongest answer?", "options": ["Planting trees near every oil field", "Methane leaks, since saved gas can be sold", "Buying offsets for all of its emissions"], "correctIndex": 1, "consequences": ["Trees do not stop the leaks.", "You start with the cut that earns money back.", "Offsets cost money and cut nothing on site."], "explanation": "Much of the 70% preventable methane can be captured and resold."}, "proReasoning": "Leading with the cut that pays for itself shows commercial sense, not just climate concern.", "commonMistake": "Jumping to offsets before fixing what leaks.", "mentalModel": "Start with the cut that pays."}, "invest": {"call": {"kind": "theCall", "situation": "Two gas producers report emissions. One has high methane leakage.", "prompt": "What does high leakage tell you?", "options": ["It is more efficient than its peers", "Nothing about how the firm runs", "It is losing sellable product and value"], "correctIndex": 2, "consequences": ["Leaking gas is the opposite of efficient.", "Leaks reveal how well assets are maintained.", "Leaks are lost revenue as well as emissions."], "explanation": "Leaked methane is gas the company could have sold."}, "proReasoning": "Investors read leakage as an operating signal: lost product and weaker upkeep.", "commonMistake": "Treating methane as only an environmental issue.", "mentalModel": "Leaks are lost revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell leak detection to gas producers.", "prompt": "What is your best sales pitch?", "options": ["Find leaks and sell the gas you save", "Detection makes your company look green", "Leaks are too small to bother finding"], "correctIndex": 0, "consequences": ["You promise a payback the buyer can count.", "Image matters less than money to a producer.", "Over 120 million tonnes a year is not small."], "explanation": "Saved gas is revenue, so detection can pay for itself."}, "proReasoning": "Founders sell paybacks. A product that recovers sellable gas is easy to justify.", "commonMistake": "Pitching image instead of money.", "mentalModel": "Sell the payback."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why methane leaks are not all fixed already.", "prompt": "What is a likely reason?", "options": ["All the leaks are already fixed", "Finding and fixing leaks takes effort and upfront cost", "Methane is not a greenhouse gas, so leaks do no harm"], "correctIndex": 1, "consequences": ["Over 120 million tonnes still leak each year.", "Payback exists, but someone must act first.", "Methane is a strong greenhouse gas."], "explanation": "The IEA says 70% is preventable with existing technology, but it still takes work and money upfront."}, "proReasoning": "Profitable fixes still need someone to spend first. That gap is where rules and tools help.", "commonMistake": "Assuming anything profitable already happened.", "mentalModel": "Profitable is not automatic."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:234b077dae91$ml$]::text[]),
($ml$47a5ceb3-2ac6-547f-8b96-798322ea2302$ml$::uuid, $ml$climatetech$ml$, 8, 3, $ml${"id": "climatetech-d8-c3", "title": "Old wells on the books", "lessonTitle": "The gas that is worth catching", "slot": 3, "type": "decide", "brief": {"headline": "You run operations at a gas producer with hundreds of old wells. Abandoned wells and coal mines emitted about 8 million tonnes of methane worldwide in 2024.", "kicker": "Decide what to do about leaking wells.", "fullText": "The fossil fuel industry emits over 120 million tonnes of methane a year, far more than official figures show, the IEA estimates. Full use of known measures could avoid about 0.1°C of warming by 2050.\n\nYour active wells leak gas you could sell. Your abandoned wells leak gas you cannot sell, but it still counts. The board wants a plan.", "sources": [{"url": "https://airqualitynews.com/headlines/methane-emissions-much-higher-than-they-need-to-be-says-iea/", "label": "Air Quality News, IEA Global Methane Tracker 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Abandoned wells and coal mines emitted about 8 million tonnes in 2024.", "Methane is the main part of natural gas.", "Official figures overstate methane from fossil fuels."], "fakeIndex": 2, "explanation": "The IEA says actual methane emissions are far higher than official figures show."}, "numbers": {"kind": "numberSense", "prompt": "Abandoned wells and mines emit about 8 of 120 million tonnes. About what share is that?", "min": 0, "max": 30, "value": 7, "unit": "%", "explanation": "About 7%. Small next to active operations, but those wells will leak for years unless sealed."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're new on the operations team. Your boss asks where to start.", "prompt": "What do you recommend first?", "options": ["Seal every abandoned well first, at any cost", "Wait for regulators to set the order", "Fix active leaks first, where saved gas pays"], "correctIndex": 2, "consequences": ["Abandoned wells earn nothing back when sealed.", "Waiting leaves cheap fixes undone.", "Early savings can fund the harder work later."], "explanation": "Active leaks lose sellable gas. Fixing them first can fund sealing old wells."}, "proReasoning": "Sequencing matters. Start with the fix that pays, and use it to fund the one that does not.", "commonMistake": "Starting with the most expensive problem because it looks worst.", "mentalModel": "Let paying fixes fund the rest."}, "invest": {"call": {"kind": "theCall", "situation": "You are evaluating this producer. It has hundreds of unsealed old wells.", "prompt": "How do you treat them?", "options": ["As a future cost to seal and monitor", "As free assets with no value or cost", "As spare capacity to restart"], "correctIndex": 0, "consequences": ["You count the liability before it hits.", "Leaking wells carry real future costs.", "Abandoned wells are not ready to produce."], "explanation": "Old wells keep leaking methane and will need sealing, which is a real cost."}, "proReasoning": "Investors count old liabilities. Unsealed wells are a cost waiting to be paid.", "commonMistake": "Ignoring liabilities that do not show up as revenue.", "mentalModel": "Count the cleanup cost."}, "build_startup": {"call": {"kind": "theCall", "situation": "You offer a cheap way to find which old wells leak most.", "prompt": "Why would this producer buy it?", "options": ["It replaces the need to seal any well", "It lets them seal the worst wells first", "It turns abandoned wells into revenue"], "correctIndex": 1, "consequences": ["Finding leaks does not stop them.", "Ranking leaks stretches a limited budget.", "Old wells do not become sellable output."], "explanation": "With hundreds of wells, knowing which leak most lets a fixed budget cut the most methane."}, "proReasoning": "Founders who help buyers prioritize make limited budgets go further.", "commonMistake": "Overpromising revenue from a cost problem.", "mentalModel": "Help them fix the worst first."}, "curiosity": {"call": {"kind": "theCall", "situation": "You learn abandoned wells keep leaking long after they stop producing.", "prompt": "Why does it matter?", "options": ["Old wells stop leaking on their own", "Abandoned well emissions do not count", "Each leak still warms the planet for years"], "correctIndex": 2, "consequences": ["They can leak for a long time.", "They emitted about 8 million tonnes in 2024.", "Unsealed wells keep emitting."], "explanation": "Abandoned wells and mines emitted about 8 million tonnes of methane in 2024."}, "proReasoning": "Some emissions outlive the business that caused them.", "commonMistake": "Thinking a closed site stops emitting.", "mentalModel": "Closed is not sealed."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:af227bb94272$ml$]::text[]),
($ml$3e63b756-cb93-56a6-b212-f912a38aed14$ml$::uuid, $ml$climatetech$ml$, 9, 1, $ml${"id": "climatetech-d9-c1", "title": "A farmer, a glacier and RWE", "lessonTitle": "Fifty-seven producers", "slot": 1, "type": "apply", "brief": {"headline": "In May 2025, a German court dismissed a Peruvian farmer's claim against utility RWE over a glacier lake. But it confirmed that big emitters can, in principle, be liable for climate damage abroad.", "kicker": "Apply the rule: can one producer be held to account?", "fullText": "Saúl Luciano Lliuya filed the case in 2015, arguing RWE should pay a share of flood protection for his home, matching its share of historical emissions, cited at about 0.47%. Lowering the lake was estimated to cost about €3.5 million.\n\nOn May 28, 2025, the Hamm court found the flood risk too low: about a 1% chance in 30 years. But it held that liability under German civil law is possible in principle, even for a small share of emissions.", "sources": [{"url": "https://cms.law/en/deu/legal-updates/hamm-higher-regional-court-dismisses-lliuya-v-rwe-climate-action-liability-on-the-merits-confirmed", "label": "CMS, Hamm court dismisses Lliuya v RWE"}, {"url": "https://www.insurancejournal.com/news/international/2024/04/04/767953.htm", "label": "Reuters via Insurance Journal, 57 producers linked to most recent CO2"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The court dismissed the claim over too low a flood risk.", "The court ordered RWE to pay for the flood works.", "The court said a small share of emissions can be enough."], "fakeIndex": 1, "explanation": "RWE paid nothing: the case was dismissed. But the principle of liability was confirmed."}, "numbers": {"kind": "numberSense", "prompt": "Flood works cost about €3.5 million, and RWE's share was cited at 0.47%. About how many thousand euros?", "min": 0, "max": 50, "value": 16, "unit": "K", "explanation": "About €16,000. A small sum, but the principle behind it could apply to many claims."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A law firm asks what the RWE ruling means for big emitters.", "prompt": "What is the key point?", "options": ["Every emitter must now pay all damages", "Liability is possible in principle, case by case", "Emitters can never be sued over climate damage"], "correctIndex": 1, "consequences": ["This claim failed on the facts.", "You capture both the loss and the principle.", "The court said liability is possible."], "explanation": "The claim lost on flood risk, but the court accepted liability in principle."}, "proReasoning": "Separate the outcome from the precedent. Lawyers and risk teams care about both.", "commonMistake": "Calling it a clean win or a clean loss for either side.", "mentalModel": "Outcome and principle can differ."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a large historical emitter.", "prompt": "What does the ruling add to its risk?", "options": ["No risk, since RWE paid nothing", "Certain loss on every future claim", "A path for future damage claims abroad"], "correctIndex": 2, "consequences": ["The principle survives the dismissal.", "Each claim still needs strong facts.", "You price a new, uncertain liability."], "explanation": "The court confirmed that a small share of emissions can ground liability."}, "proReasoning": "Investors price new legal paths as risk, even when the first case fails.", "commonMistake": "Reading a dismissal as the end of the risk.", "mentalModel": "A failed case can open a door."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup links local climate damage to its causes with data.", "prompt": "What did this case show you is needed?", "options": ["Strong evidence of how likely the damage is", "Nothing, since the claim failed", "Proof that one firm caused all warming"], "correctIndex": 0, "consequences": ["The case turned on how probable the flood was.", "It failed for lack of risk evidence.", "A share of emissions was enough in principle."], "explanation": "The claim failed because the flood risk was about 1% in 30 years. Evidence decided it."}, "proReasoning": "Founders in climate data should study what decided the case. Here, the probability of harm.", "commonMistake": "Assuming a failed case means no demand for evidence.", "mentalModel": "Evidence decides these cases."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear a Peruvian farmer lost his case against RWE.", "prompt": "Did he gain anything?", "options": ["Yes, RWE paid him millions", "Yes, the court accepted liability in principle", "No, the court rejected the whole idea outright"], "correctIndex": 1, "consequences": ["RWE paid nothing.", "The principle may help future claims.", "The court backed the idea in principle."], "explanation": "The case was dismissed on the facts, but the legal principle was confirmed."}, "proReasoning": "In law, losing a case can still move the rules forward.", "commonMistake": "Judging a case only by who won.", "mentalModel": "Look past the verdict to the rule."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:abbea8bcdcba$ml$]::text[]),
($ml$e893e09f-69f8-5cdd-9df2-6dd54c091f4f$ml$::uuid, $ml$climatetech$ml$, 9, 2, $ml${"id": "climatetech-d9-c2", "title": "Two kinds of concentration", "lessonTitle": "Fifty-seven producers", "slot": 2, "type": "connect", "brief": {"headline": "From 2016 to 2022, 57 producers were linked to 80% of fossil and cement CO2. Four countries, China, the US, India and the EU, emit about 59% of fossil CO2.", "kicker": "Connect day 3 and day 9: few countries, few producers.", "fullText": "Day 3 showed that a few big emitters decide most of the outcome. The Carbon Majors report shows the same pattern on the supply side: 57 producers, including nation-states, state-owned and investor-owned companies.\n\nThe top three were Saudi Aramco, Russia's Gazprom and Coal India, all state-owned. Most producers increased output after the 2015 Paris Agreement.", "sources": [{"url": "https://www.insurancejournal.com/news/international/2024/04/04/767953.htm", "label": "Reuters via Insurance Journal, 57 producers linked to most recent CO2"}, {"url": "https://www.cger.nies.go.jp/gcp/pdf/20251113/CarbonBudget2025_CICERO_press_E.pdf", "label": "CICERO, Global Carbon Budget 2025 release"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is this producer state-owned or investor-owned?", "buckets": ["State-owned", "Investor-owned"], "items": [{"text": "Saudi Aramco", "bucket": 0}, {"text": "Gazprom", "bucket": 0}, {"text": "Coal India", "bucket": 0}, {"text": "ExxonMobil", "bucket": 1}, {"text": "Shell", "bucket": 1}], "explanation": "The top three on the list are state-owned. Investor-owned majors like ExxonMobil and Shell are on it too."}, "numbers": {"kind": "numberSense", "prompt": "57 producers were linked to 80% of fossil and cement CO2. What share is left for everyone else?", "min": 0, "max": 100, "value": 20, "unit": "%", "explanation": "About 20%. Supply is even more concentrated than emissions by country."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A climate think tank asks who holds the most power over fossil supply.", "prompt": "What do you answer?", "options": ["Millions of drivers making daily choices", "Investor-owned oil majors above all", "A few producers, mostly owned by governments"], "correctIndex": 2, "consequences": ["Demand matters, but supply is highly concentrated.", "The top three producers are state-owned.", "You name the concentrated, state-led supply side."], "explanation": "57 producers supply 80% of the CO2, and the largest are state-owned."}, "proReasoning": "Naming who controls supply shows you see both sides of the market.", "commonMistake": "Focusing only on consumers or only on listed companies.", "mentalModel": "Look at who controls supply."}, "invest": {"call": {"kind": "theCall", "situation": "You plan shareholder pressure on fossil producers.", "prompt": "Where can it reach?", "options": ["Investor-owned firms, not the state-owned top three", "All 57 producers equally well", "Only the top three, which happen to be state-owned"], "correctIndex": 0, "consequences": ["You aim where shareholders have a vote.", "State-owned firms answer to governments.", "Shareholders have little say over state firms."], "explanation": "Saudi Aramco, Gazprom and Coal India are state-owned, so investor pressure has limited reach there."}, "proReasoning": "Investors match tools to owners. Engagement works where shareholders actually vote.", "commonMistake": "Expecting investor pressure to move state producers.", "mentalModel": "Match the tool to the owner."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell methane monitoring to fossil producers.", "prompt": "Why does concentration help you?", "options": ["It means there are no real customers left", "A few big buyers cover most of the market", "It makes every producer tiny"], "correctIndex": 1, "consequences": ["A few large buyers are still buyers.", "Winning a few accounts reaches most volume.", "Concentration means a few are huge."], "explanation": "57 producers supply 80% of the CO2, so a few contracts reach most of the volume."}, "proReasoning": "Concentrated markets let founders reach most volume through a few large customers.", "commonMistake": "Spreading sales across thousands of small targets.", "mentalModel": "Few buyers, most volume."}, "curiosity": {"call": {"kind": "theCall", "situation": "You assumed oil companies on the stock market emit the most.", "prompt": "What does the list show?", "options": ["Only listed firms appear on the list", "Small producers dominate the total", "The top three are owned by governments"], "correctIndex": 2, "consequences": ["Nation-states and state firms are on it.", "57 producers account for 80%.", "Saudi Aramco, Gazprom and Coal India lead."], "explanation": "The three largest producers are state-owned."}, "proReasoning": "Behind most fossil supply sit governments, not just companies.", "commonMistake": "Assuming the biggest emitters are the most famous brands.", "mentalModel": "Check who owns the producer."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a6a2d5e33a2e$ml$]::text[]),
($ml$0cc76355-64fc-5060-b6d5-651cd79f5d25$ml$::uuid, $ml$climatetech$ml$, 9, 3, $ml${"id": "climatetech-d9-c3", "title": "Engage or walk away", "lessonTitle": "Fifty-seven producers", "slot": 3, "type": "decide", "brief": {"headline": "You sit on a pension fund board. Members want action on the Carbon Majors list. 57 producers were linked to 80% of fossil and cement CO2 from 2016 to 2022.", "kicker": "Decide how your fund should act.", "fullText": "The list includes nation-states, state-owned companies and investor-owned companies. The top three were state-owned. Most producers raised output after the 2015 Paris Agreement.\n\nAn earlier edition of the report was cited in a Belgian farmer's lawsuit against TotalEnergies. Your fund owns shares in several investor-owned producers on the list.", "sources": [{"url": "https://www.insurancejournal.com/news/international/2024/04/04/767953.htm", "label": "Reuters via Insurance Journal, 57 producers linked to most recent CO2"}]}, "evidence": {"kind": "faceOff", "prompt": "Where does a shareholder vote carry more weight?", "left": {"name": "An investor-owned oil major", "note": "Listed, with public shareholders"}, "right": {"name": "A state-owned producer", "note": "Controlled by its government"}, "correctIndex": 0, "explanation": "Shareholders vote at listed companies. State-owned producers answer to their governments."}, "numbers": {"kind": "numberSense", "prompt": "What share of fossil and cement CO2 were the 57 producers linked to?", "min": 0, "max": 100, "value": 80, "unit": "%", "explanation": "About 80% from 2016 to 2022."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the fund's junior analyst. The board asks for options.", "prompt": "What do you put first?", "options": ["Push holdings on output plans, then review", "Sell everything today without any plan", "Do nothing, since members will forget"], "correctIndex": 0, "consequences": ["You offer a plan with a clear next step.", "Selling ends your vote at those firms.", "Members asked for action."], "explanation": "Most producers raised output after Paris. Engagement with a review date tests whether that changes."}, "proReasoning": "Good analysts give boards a path with checkpoints, not a single dramatic move.", "commonMistake": "Recommending an all-or-nothing choice with no follow-up.", "mentalModel": "Offer a path with checkpoints."}, "invest": {"call": {"kind": "theCall", "situation": "The board debates selling its oil major shares.", "prompt": "What is the trade-off?", "options": ["There is no trade-off either way", "Selling lowers exposure but gives up the vote", "Selling cuts the firm's emissions directly"], "correctIndex": 1, "consequences": ["Each choice gives up something.", "You weigh risk against influence.", "Another buyer takes the shares; output is unchanged."], "explanation": "Selling removes your risk and your voice. The producer keeps operating either way."}, "proReasoning": "Investors weigh exposure against influence. Divesting and engaging each give something up.", "commonMistake": "Believing a sale reduces the company's emissions.", "mentalModel": "Divest for risk, engage for influence."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build a tool that tracks producers' output plans against climate goals.", "prompt": "Who is your best first customer?", "options": ["The state-owned producers themselves", "Drivers choosing where to buy fuel", "Funds that engage with producers they own"], "correctIndex": 2, "consequences": ["They are unlikely to pay to be tracked.", "Drivers have little use for producer data.", "Engaging funds need exactly this evidence."], "explanation": "Funds pressing producers on output need data to hold them to account."}, "proReasoning": "Founders sell to whoever needs the evidence to act. Engaged shareholders do.", "commonMistake": "Selling to the party being scrutinized.", "mentalModel": "Sell to whoever acts on the data."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder if selling oil shares cuts emissions.", "prompt": "What's the honest answer?", "options": ["Not directly; someone else buys the shares", "Yes, each sale shuts down a well", "Yes, the share price falls and output stops"], "correctIndex": 0, "consequences": ["The company keeps producing.", "Shares change hands; wells keep running.", "One fund's sale rarely changes output."], "explanation": "Shares pass to another owner, and the producer keeps operating."}, "proReasoning": "Ownership changes hands; production does not stop with it.", "commonMistake": "Thinking a share sale is the same as closing a well.", "mentalModel": "Selling shifts ownership, not output."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d5f5eb79abb5$ml$]::text[]),
($ml$352b2243-67c5-50ad-b1df-7630640dceb9$ml$::uuid, $ml$climatetech$ml$, 10, 1, $ml${"id": "climatetech-d10-c1", "title": "Capturing half a cement plant", "lessonTitle": "Steel and cement: the hard 15%", "slot": 1, "type": "apply", "brief": {"headline": "In June 2025, Heidelberg Materials opened carbon capture at its Brevik cement plant in Norway, the first at industrial scale in cement. It is built to capture about 400,000 tonnes of CO2 a year.", "kicker": "Apply the rule: what does cleaning a hard sector take?", "fullText": "The facility captures about half of the plant's emissions. The CO2 is liquefied, shipped to a terminal on Norway's west coast and piped into permanent storage under the North Sea by Northern Lights, run by Equinor, Shell and TotalEnergies.\n\nThe project is part of Norway's government Longship program. Heidelberg sells the resulting cement as evoZero. Cement makes about 7% of global CO2, and the IEA calls it notoriously hard to abate.", "sources": [{"url": "https://www.heidelbergmaterials.com/en/pr-2025-06-18", "label": "Heidelberg Materials, Brevik CCS opening"}, {"url": "https://www.gasworld.com/story/iea-report-lays-out-strategy-for-zero-emission-steel-and-cement/2094112.article", "label": "gasworld, IEA strategy for zero-emission steel and cement"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow Brevik's CO2 from kiln to storage.", "steps": ["The kiln releases CO2 while making cement", "The capture plant separates about half of it", "The CO2 is liquefied", "Ships carry it to a west coast terminal", "A pipeline sends it under the North Sea"], "explanation": "Capture, liquefy, ship, pipe, store. Each step needs its own infrastructure, which is why it took a national program."}, "numbers": {"kind": "numberSense", "prompt": "Brevik captures about 400,000 tonnes, half its emissions. About how many thousand tonnes does the plant emit?", "min": 0, "max": 2000, "value": 800, "unit": "K", "explanation": "About 800,000 tonnes a year. Even this first plant leaves half its CO2 uncaptured."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A cement company asks what Brevik shows about decarbonizing its plants.", "prompt": "What is the honest lesson?", "options": ["It is cheap and easy for any cement plant", "It proves capture cannot work in cement", "It works, but needs storage and public support"], "correctIndex": 2, "consequences": ["It relied on a national program and shared storage.", "It is running at industrial scale.", "You see both the success and its conditions."], "explanation": "Brevik captures CO2 at scale, but depends on Northern Lights storage and the Longship program."}, "proReasoning": "Good analysts describe a first-of-a-kind project with its conditions, not just its headline.", "commonMistake": "Calling one supported project proof that every plant can follow cheaply.", "mentalModel": "Name the result and what made it possible."}, "invest": {"call": {"kind": "theCall", "situation": "You weigh shares in Heidelberg Materials after the Brevik opening.", "prompt": "What does evoZero offer the company?", "options": ["A low-carbon product buyers may pay more for", "An end to all of its carbon costs for good", "Nothing beyond good press coverage"], "correctIndex": 0, "consequences": ["You see a product that can earn a premium.", "It captures half of one plant, not every plant.", "It is a real product sold to customers."], "explanation": "evoZero is cement with captured emissions, a product that can command a premium from some buyers."}, "proReasoning": "Investors look for products that turn a cost into revenue. Low-carbon cement is one attempt.", "commonMistake": "Overstating one plant's effect on a whole company's emissions.", "mentalModel": "Look for the product, not just the project."}, "build_startup": {"call": {"kind": "theCall", "situation": "Brevik's CO2 travels by ship and pipe to storage.", "prompt": "Where might a startup fit in?", "options": ["Selling cement with no capture at all", "Cheaper ways to move or store captured CO2", "Building another cement company"], "correctIndex": 1, "consequences": ["That ignores the problem entirely.", "You target the costly links after capture.", "A cement company is a huge capital bet."], "explanation": "Capture is only the first step. Transport and storage add cost and complexity."}, "proReasoning": "Founders look at the whole chain. Transport and storage are often where costs pile up.", "commonMistake": "Focusing only on the capture step.", "mentalModel": "Look at the whole chain."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why cement is so hard to clean up.", "prompt": "What makes it special?", "options": ["Cement plants use very little energy at all", "Cement is a small source of CO2", "Making it releases CO2 from the rock itself"], "correctIndex": 2, "consequences": ["Kilns run very hot and use lots of energy.", "It makes about 7% of global CO2.", "Even clean fuel would not remove those emissions."], "explanation": "Cement releases CO2 chemically, not just from fuel. That is why capture matters."}, "proReasoning": "Some emissions come from chemistry, not fuel. Those need capture or new materials.", "commonMistake": "Thinking clean power alone can decarbonize cement.", "mentalModel": "Chemistry emissions need capture."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3369a1a8e664$ml$]::text[]),
($ml$6a9c41c6-8957-58ec-abe4-be446e1a976f$ml$::uuid, $ml$climatetech$ml$, 10, 2, $ml${"id": "climatetech-d10-c2", "title": "The price that pays for capture", "lessonTitle": "Steel and cement: the hard 15%", "slot": 2, "type": "connect", "brief": {"headline": "Steel and cement make about 15% of global CO2, and the IEA calls both hard to abate because cuts are costly. In the EU, heavy industry needs an allowance for every tonne.", "kicker": "Connect day 5 and day 10: a carbon price makes costly cuts add up.", "fullText": "Steel produces about 8% of global CO2 and cement about 7%. Cleaning them up is expensive, which is why progress is slow.\n\nDay 5 showed how the EU system works: heavy industry is covered, every tonne needs an allowance, and the cap shrinks each year. The higher the price of each tonne, the more expensive cuts start to pay for themselves.", "sources": [{"url": "https://www.gasworld.com/story/iea-report-lays-out-strategy-for-zero-emission-steel-and-cement/2094112.article", "label": "gasworld, IEA strategy for zero-emission steel and cement"}, {"url": "https://carbonmarketwatch.org/2024/02/29/faq-what-is-the-eu-emissions-trading-system-eu-ets/", "label": "Carbon Market Watch, EU ETS FAQ"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Steel and cement are about 15% of global CO2.", "EU heavy industry needs allowances for its emissions.", "Cutting steel and cement emissions is cheap and easy."], "fakeIndex": 2, "explanation": "The IEA calls both sectors hard to abate precisely because cutting their emissions is costly."}, "numbers": {"kind": "numberSense", "prompt": "About what share of global CO2 do steel and cement produce together?", "min": 0, "max": 50, "value": 15, "unit": "%", "explanation": "About 15%: steel about 8% and cement about 7%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A policy team asks why carbon prices matter most for heavy industry.", "prompt": "What do you say?", "options": ["Costly cuts only pay off once tonnes cost money", "Heavy industry already pays nothing for carbon", "Carbon prices make cuts cheaper to build"], "correctIndex": 0, "consequences": ["You link price to the economics of hard cuts.", "EU heavy industry already needs allowances.", "Prices change the payoff, not the build cost."], "explanation": "Hard-to-abate cuts are expensive. A carbon price makes avoiding each tonne worth money."}, "proReasoning": "Explaining how a price shifts the business case is central to climate policy work.", "commonMistake": "Thinking a price lowers the cost of the technology itself.", "mentalModel": "Price changes the payoff of a cut."}, "invest": {"call": {"kind": "theCall", "situation": "You model a steel company inside the EU carbon market.", "prompt": "What happens as the cap shrinks?", "options": ["Nothing changes for steelmakers", "Its carbon costs rise unless it cuts emissions", "Its costs fall now that fewer permits exist"], "correctIndex": 1, "consequences": ["Steel is inside the system.", "You see cuts become a hedge against rising costs.", "Fewer permits tend to mean higher prices."], "explanation": "A shrinking cap raises the cost of every tonne for an emitter that does not cut."}, "proReasoning": "Investors treat emissions as a growing cost line for covered heavy industry.", "commonMistake": "Ignoring carbon costs in a steelmaker's margins.", "mentalModel": "Emissions are a rising cost line."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup makes a cleaner steel process that costs more today.", "prompt": "Where do you sell first?", "options": ["Where carbon is free to emit", "Anywhere, since the carbon price does not matter", "Where carbon is priced, so savings offset cost"], "correctIndex": 2, "consequences": ["With free carbon, your premium has no offset.", "Buyers compare total costs.", "The carbon price narrows your cost gap."], "explanation": "In a priced market, each tonne avoided saves money, which helps cover a higher process cost."}, "proReasoning": "Founders with costlier clean processes start where carbon prices close the gap.", "commonMistake": "Selling a premium product where carbon costs nothing.", "mentalModel": "Start where carbon costs money."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why steelmakers would ever pay more to cut emissions.", "prompt": "What changes their math?", "options": ["A carbon price on each tonne they emit", "Nothing, since they never would do it", "Lower demand for steel"], "correctIndex": 0, "consequences": ["Avoided tonnes become savings.", "In priced markets, they already do.", "Demand stays high for buildings and roads."], "explanation": "When each tonne costs money, cutting emissions can become the cheaper option over time."}, "proReasoning": "Prices turn a moral choice into a business choice.", "commonMistake": "Assuming companies only cut emissions when forced by bans.", "mentalModel": "Prices change the math."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:88ecf8e9c590$ml$]::text[]),
($ml$514001a5-6078-51d9-8365-68e0499784a9$ml$::uuid, $ml$climatetech$ml$, 10, 3, $ml${"id": "climatetech-d10-c3", "title": "A bridge and its concrete", "lessonTitle": "Steel and cement: the hard 15%", "slot": 3, "type": "decide", "brief": {"headline": "You run procurement for a city building a new bridge. Low-carbon concrete costs more. Steel makes about 8% of global CO2 and cement about 7%.", "kicker": "Decide what the city should buy.", "fullText": "Cities, roads and wind turbines all need steel and concrete, so using less of them is rarely the answer. The IEA calls both sectors hard to abate because cutting their emissions is costly.\n\nLarge public buyers can create early demand for cleaner materials. Your budget is fixed, and the council wants the bridge on time.", "sources": [{"url": "https://www.gasworld.com/story/iea-report-lays-out-strategy-for-zero-emission-steel-and-cement/2094112.article", "label": "gasworld, IEA strategy for zero-emission steel and cement"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why can a city buying low-carbon concrete matter beyond one bridge?", "options": ["It removes cement from the bridge completely", "It forces every country to switch materials", "Early demand helps cleaner suppliers reach scale"], "correctIndex": 2, "explanation": "Public buyers give cleaner suppliers early orders, which helps their costs fall over time."}, "numbers": {"kind": "numberSense", "prompt": "About what share of global CO2 comes from cement?", "min": 0, "max": 30, "value": 7, "unit": "%", "explanation": "About 7%, close to steel at about 8%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the procurement officer drafting the tender.", "prompt": "What do you write in?", "options": ["Ban concrete from the bridge design", "Score bids on cost and on embodied carbon", "Choose the cheapest bid, nothing else"], "correctIndex": 1, "consequences": ["A bridge still needs concrete.", "You reward cleaner bids without ignoring cost.", "Cheapest only leaves carbon out entirely."], "explanation": "Scoring carbon alongside cost lets cleaner suppliers compete within the budget."}, "proReasoning": "Procurement officers can shape markets by what they score, not just what they buy.", "commonMistake": "Treating price as the only criterion for a long-lived asset.", "mentalModel": "What you score is what you get."}, "invest": {"call": {"kind": "theCall", "situation": "Many cities start scoring embodied carbon in tenders.", "prompt": "Which supplier benefits?", "options": ["Suppliers that ignore emissions", "Neither, since the lowest price always wins", "Cement makers with lower-carbon products"], "correctIndex": 2, "consequences": ["They lose points in carbon-scored tenders.", "Scoring changes what wins.", "Public demand rewards cleaner products."], "explanation": "When buyers score carbon, lower-carbon suppliers win more bids."}, "proReasoning": "Investors watch procurement rules. They can shift demand faster than regulation.", "commonMistake": "Assuming price alone decides public contracts.", "mentalModel": "Procurement rules move demand."}, "build_startup": {"call": {"kind": "theCall", "situation": "You make a lower-carbon cement additive.", "prompt": "Who is your best early customer?", "options": ["Public buyers that score carbon", "Private builders who only want the cheapest", "Countries with no construction plans"], "correctIndex": 0, "consequences": ["They reward your lower carbon content.", "They will not pay for your advantage yet.", "No construction means no demand."], "explanation": "Buyers that score embodied carbon value exactly what your product offers."}, "proReasoning": "Founders find the buyer whose rules reward their advantage.", "commonMistake": "Selling a carbon advantage to buyers who only score price.", "mentalModel": "Find buyers who score your edge."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why we cannot just build without concrete.", "prompt": "What's the realistic answer?", "options": ["Bridges do not use much concrete", "Concrete is essential, so we must clean it up", "Concrete is easy to replace with wood everywhere"], "correctIndex": 1, "consequences": ["Bridges use a great deal.", "Cleaner concrete beats impossible substitutes.", "No material replaces concrete everywhere."], "explanation": "Cities, roads and turbines all need concrete. Cutting its emissions matters more than cutting its use."}, "proReasoning": "For essential materials, the path is cleaner production, not doing without.", "commonMistake": "Assuming every high-carbon material can simply be replaced.", "mentalModel": "Clean it up, do not wish it away."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:aebd99b62408$ml$]::text[]),
($ml$490f7a56-e4f1-5882-a829-9e917a575095$ml$::uuid, $ml$climatetech$ml$, 11, 1, $ml${"id": "climatetech-d11-c1", "title": "Pushed to 2034", "lessonTitle": "The methane fee that never started", "slot": 1, "type": "apply", "brief": {"headline": "A 2025 US budget law postponed the methane charge so it is first assessed on 2034 emissions, at $1,500 per tonne. It had been due from 2024 emissions.", "kicker": "Apply the rule: is it a law in force or a law on paper?", "fullText": "The 2022 Inflation Reduction Act set a charge on excess methane from oil and gas facilities: $900 per tonne for 2024 emissions, $1,200 for 2025 and $1,500 from 2026.\n\nIn March 2025, Congress overturned the EPA rule that would have collected it. Then the One Big Beautiful Bill Act postponed the charge itself, so it is first assessed on 2034 emissions, at $1,500 a tonne. The charge stays in law, but no one pays it for nearly a decade.", "sources": [{"url": "https://www.iea.org/policies/18187-waste-emissions-charge-for-petroleum-and-natural-gas-systems", "label": "IEA, Waste Emissions Charge policy"}, {"url": "https://www.everycrsreport.com/reports/R48475.html", "label": "Congressional Research Service, the methane emissions charge"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the methane charge's history in order.", "steps": ["The 2022 law sets a charge on excess methane", "EPA writes a rule to collect it", "Congress overturns the EPA rule in March 2025", "A 2025 budget law postpones the charge", "The charge first applies to 2034 emissions"], "explanation": "A law, a rule, a repeal of the rule, then a postponement. The charge exists on paper but is not collected."}, "numbers": {"kind": "numberSense", "prompt": "The charge was first due on 2024 emissions and now on 2034 emissions. How many years later is that?", "min": 0, "max": 25, "value": 10, "unit": "years", "explanation": "Ten years. The law still sets a charge, but it will not bite for a decade."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An oil company compliance team asks what the methane charge means for them today.", "prompt": "What is accurate?", "options": ["It is in law but not assessed until 2034 emissions", "It was fully repealed, so it can be forgotten", "They owe $1,500 per tonne this year"], "correctIndex": 0, "consequences": ["You give the exact status and the date to watch.", "The charge stays in law, only postponed.", "Nothing is due until the 2034 emissions year."], "explanation": "The 2025 law postponed the charge; it remains in the statute for 2034 emissions."}, "proReasoning": "Compliance teams need the exact status: in law, not collected, date set. That precision matters.", "commonMistake": "Calling a postponed charge repealed.", "mentalModel": "State the status and the date."}, "invest": {"call": {"kind": "theCall", "situation": "You value a US gas producer with high methane leakage.", "prompt": "How do you treat the charge?", "options": ["Gone forever, so no risk at all", "A distant risk that a future law could revive", "A cost the company already pays this year"], "correctIndex": 1, "consequences": ["It remains in law and could change again.", "You keep a low but real risk in your model.", "It is not assessed until 2034 emissions."], "explanation": "Postponed to 2034, the charge is a long-dated risk, and future Congresses can change it again."}, "proReasoning": "Investors keep postponed rules in the model as long-dated risks, not zero.", "commonMistake": "Deleting a risk from the model because it was delayed.", "mentalModel": "Delayed is not deleted."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your leak detection startup counted on the US charge to drive sales.", "prompt": "How do you adjust?", "options": ["Shut down, since demand is gone", "Wait for 2034 and hope", "Sell on the value of recovered gas"], "correctIndex": 2, "consequences": ["Saved gas still has value to sell.", "Waiting a decade means no company.", "You lean on the reason that never depended on law."], "explanation": "Without the charge, leak detection still pays through gas that can be sold."}, "proReasoning": "Founders should not build on one policy. A business case that stands without it survives repeal.", "commonMistake": "Building a company whose only reason to exist is one regulation.", "mentalModel": "Have a case that stands without the rule."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that the methane fee was killed, then that it still exists.", "prompt": "Which is it?", "options": ["Both: the rule was killed, the law delayed", "It was killed completely and for good in 2025", "It is being collected right now"], "correctIndex": 0, "consequences": ["You separate the rule from the law behind it.", "The charge itself stays in law for 2034.", "No charge is collected until then."], "explanation": "Congress overturned the EPA rule, then a budget law postponed the charge to 2034 emissions."}, "proReasoning": "In US policy, the law, the rule and the date can each change separately.", "commonMistake": "Treating \"killed\" in a headline as the whole story.", "mentalModel": "Separate the law, the rule and the date."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7c261293ae7d$ml$]::text[]),
($ml$a1bfbd58-32cb-5c27-8aee-319048b64c83$ml$::uuid, $ml$climatetech$ml$, 11, 2, $ml${"id": "climatetech-d11-c2", "title": "Leaks still worth fixing", "lessonTitle": "The methane fee that never started", "slot": 2, "type": "connect", "brief": {"headline": "At $900 per tonne, the US methane charge equaled about $32 per tonne of CO2 equivalent. It is now postponed, but the IEA says 70% of energy sector methane is preventable and much can be resold.", "kicker": "Connect day 8 and day 11: why leaks are worth fixing without a fee.", "fullText": "Day 8 showed that leaked methane is gas a company could have sold, and that existing technology could prevent 70% of energy sector methane.\n\nDay 11 shows the charge that was meant to add a cost on top: $900 per tonne of methane for 2024, about $32 per tonne of CO2 equivalent, rising to about $54. With the charge postponed, the sales case remains.", "sources": [{"url": "https://www.everycrsreport.com/reports/R48475.html", "label": "Congressional Research Service, the methane emissions charge"}, {"url": "https://airqualitynews.com/headlines/methane-emissions-much-higher-than-they-need-to-be-says-iea/", "label": "Air Quality News, IEA Global Methane Tracker 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "With the US charge postponed, which reason to fix leaks remains?", "options": ["Captured gas can still be sold", "The charge is still due this year", "Leaks no longer warm the climate"], "correctIndex": 0, "explanation": "The sales value of captured gas never depended on the charge."}, "numbers": {"kind": "numberSense", "prompt": "$900 a tonne of methane matched about $32 a tonne of CO2e. One tonne of methane counts as about how many of CO2?", "min": 0, "max": 80, "value": 28, "unit": "t", "explanation": "900 divided by 32 is about 28. Each tonne of methane counts like about 28 tonnes of CO2."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A gas producer asks whether its leak program still makes sense after the charge was postponed.", "prompt": "What do you advise?", "options": ["Double it to get ahead of 2034", "Keep the cuts that pay through saved gas", "Cancel the whole leak program at once"], "correctIndex": 1, "consequences": ["Doubling ignores which cuts actually pay.", "You keep the profitable part of the program.", "You throw away cuts that paid for themselves."], "explanation": "Much captured methane can be resold, so many fixes pay off without the charge."}, "proReasoning": "Advisers separate cuts that pay on their own from cuts that needed the policy.", "commonMistake": "Treating a whole program as dependent on one policy.", "mentalModel": "Keep the cuts that pay for themselves."}, "invest": {"call": {"kind": "theCall", "situation": "A producer scraps its leak repair budget after the charge is postponed.", "prompt": "What does that signal?", "options": ["It is managing costs wisely", "Nothing at all about how it runs its operations", "It may be leaving sellable gas on the table"], "correctIndex": 2, "consequences": ["Cutting repairs can cost more in lost gas.", "Leak repair is an operating choice.", "You read it as lost revenue and weaker upkeep."], "explanation": "Leaked methane is product it could have sold. Stopping repairs can cost revenue."}, "proReasoning": "Investors notice when firms cut spending that pays back, just because a rule moved.", "commonMistake": "Rewarding short-term savings that lose product.", "mentalModel": "Watch for savings that lose revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "You pitch leak detection to a US producer after the postponement.", "prompt": "Which number leads your pitch?", "options": ["The value of the gas you help recover", "The $1,500 charge due in 2034", "The size of the methane fee in 2024"], "correctIndex": 0, "consequences": ["You sell a payback they get now.", "A charge years away is weak urgency.", "That fee was never collected."], "explanation": "The recovered gas is value today. The charge is years away."}, "proReasoning": "Founders lead with today's money, not a policy that may change again.", "commonMistake": "Selling on a charge no one pays yet.", "mentalModel": "Lead with money today."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why methane counts so much more than CO2.", "prompt": "What does the $900 vs $32 math show?", "options": ["The two gases warm the same amount", "Each methane tonne warms like about 28 of CO2", "Methane is cheaper to emit than CO2 per tonne"], "correctIndex": 1, "consequences": ["Methane warms much more per tonne.", "Methane is a far stronger warming gas.", "The charge per tonne was far higher."], "explanation": "$900 per tonne of methane matched about $32 per tonne of CO2e, a ratio of about 28."}, "proReasoning": "Converting to CO2 equivalent lets you compare gases on one scale.", "commonMistake": "Comparing gases by weight alone.", "mentalModel": "Compare in CO2 equivalent."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:019b574627d2$ml$]::text[]),
($ml$16c6679b-534f-53f0-a239-3939021f21dc$ml$::uuid, $ml$climatetech$ml$, 11, 3, $ml${"id": "climatetech-d11-c3", "title": "Plan for which rule?", "lessonTitle": "The methane fee that never started", "slot": 3, "type": "decide", "brief": {"headline": "You run a gas operator emitting about 30,000 tonnes of CO2 equivalent a year, above the 25,000-tonne threshold in the 2022 methane charge. You must set a ten-year spending plan.", "kicker": "Decide how to plan around a rule that keeps moving.", "fullText": "The charge applied only to facilities emitting at least 25,000 tonnes of CO2 equivalent a year. Set at $900 per tonne of methane for 2024 and $1,500 from 2026, it would have equaled about $32, then $54, per tonne of CO2 equivalent.\n\nIn March 2025, Congress used the Congressional Review Act to cancel the EPA rule, but the underlying law was not repealed. Researchers said it was uncertain how, or whether, the charge could still be applied.", "sources": [{"url": "https://www.everycrsreport.com/reports/R48475.html", "label": "Congressional Research Service, the methane emissions charge"}, {"url": "https://www.iea.org/policies/18187-waste-emissions-charge-for-petroleum-and-natural-gas-systems", "label": "IEA, Waste Emissions Charge policy"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Facilities under 25,000 tonnes a year were exempt.", "At $1,500, the charge equals about $54 per tonne CO2e.", "The March 2025 vote repealed the 2022 law itself."], "fakeIndex": 2, "explanation": "Congress canceled the EPA rule. The charge in the 2022 law itself remained."}, "numbers": {"kind": "numberSense", "prompt": "The charge applied to facilities above how many thousand tonnes of CO2e a year?", "min": 0, "max": 100, "value": 25, "unit": "K", "explanation": "25,000 tonnes. Your 30,000-tonne operation sits above the line."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the operator's planning analyst. The CFO asks how to treat the charge.", "prompt": "What do you recommend?", "options": ["Ignore it, since the rule was canceled", "Budget the full charge every single year from now", "Plan for it as a later risk, with cheap fixes now"], "correctIndex": 2, "consequences": ["The law remains and could return.", "Nothing is due before 2034 emissions.", "You hedge without overspending."], "explanation": "A law on the books is not a rule in force. Treat it as a risk, and do the fixes that pay anyway."}, "proReasoning": "Planners turn policy uncertainty into scenarios rather than a single bet.", "commonMistake": "Planning as if a moving rule were either certain or dead.", "mentalModel": "Scenario plan around moving rules."}, "invest": {"call": {"kind": "theCall", "situation": "You're a lender to this operator over ten years.", "prompt": "What protects your loan?", "options": ["Lower leakage now, whatever the rule does", "A bet that methane rules never return", "A bet that the charge returns next year"], "correctIndex": 0, "consequences": ["You reduce exposure under any policy path.", "Rules have changed twice already.", "It is postponed to 2034 emissions."], "explanation": "Cutting leakage protects the borrower in every scenario."}, "proReasoning": "Lenders prefer borrowers whose risks fall in every policy scenario.", "commonMistake": "Underwriting a loan on one political outcome.", "mentalModel": "Prefer moves that win in every scenario."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell compliance software for methane rules that keep changing.", "prompt": "What feature matters most?", "options": ["No reporting at all until 2034", "Easy updates when rules or dates change", "One fixed version of the rule built in forever"], "correctIndex": 1, "consequences": ["Monitoring and reporting go on regardless.", "Customers need tools that keep up with change.", "A fixed rule goes stale fast."], "explanation": "The charge has moved twice. Software that adapts is worth more than one that hard-codes a rule."}, "proReasoning": "Founders in regulated markets build for change, because rules rarely stay put.", "commonMistake": "Hard-coding one version of a moving rule.", "mentalModel": "Build for rules that move."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder how a law can exist but not be applied.", "prompt": "What makes that possible?", "options": ["Laws apply themselves automatically", "The law was never actually passed", "The rule to collect it was canceled"], "correctIndex": 2, "consequences": ["Agencies usually write rules to apply laws.", "It passed in 2022.", "Without an agency rule, the charge sat unused."], "explanation": "Congress canceled the EPA rule, so the charge in the law had no way to be collected."}, "proReasoning": "Laws often need agency rules to work. Remove the rule and the law can sit idle.", "commonMistake": "Assuming a law works on its own.", "mentalModel": "A law often needs a rule to work."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:53634e157c7f$ml$]::text[]),
($ml$40a1e93e-08b6-5c18-b2f5-79cbe5bfde06$ml$::uuid, $ml$climatetech$ml$, 12, 1, $ml${"id": "climatetech-d12-c1", "title": "Texas's giant air scrubber", "lessonTitle": "Pulling CO2 from the air", "slot": 1, "type": "apply", "brief": {"headline": "Occidental's Stratos plant in Texas is designed to remove 500,000 tonnes of CO2 from the air a year. After first commissioning, a problem with non-process parts delayed it, and its cost rose to $1.2 billion.", "kicker": "Apply the rule: capacity is a promise until tonnes are measured.", "fullText": "Stratos, in Ector County, was first expected online by the end of 2024, then by the end of 2025. Occidental said the capture technology was performing as expected, but non-process components needed repair, and gave no new start date.\n\nThe project's cost rose by $100 million to $1.2 billion. BlackRock helped fund it in 2024. Climeworks' Mammoth in Iceland, built for 36,000 tonnes a year, captured 750 tonnes in its first ten months.", "sources": [{"url": "https://carbonherald.com/occidentals-stratos-dac-facility-delayed-by-unexpected-component-issue/", "label": "Carbon Herald, Stratos DAC plant delayed"}, {"url": "https://www.swissinfo.ch/eng/climate-solutions/why-swiss-carbon-removal-start-up-climeworks-faces-serious-headwinds/89386618", "label": "SWI swissinfo.ch, why Climeworks faces serious headwinds"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plant is designed to capture more CO2 a year?", "left": {"name": "Stratos, Texas", "note": "Occidental, delayed after commissioning"}, "right": {"name": "Mammoth, Iceland", "note": "Climeworks, 750 tonnes in ten months"}, "correctIndex": 0, "explanation": "Stratos is designed for 500,000 tonnes a year, Mammoth for 36,000. Neither design figure is a measured result."}, "numbers": {"kind": "numberSense", "prompt": "Stratos cost $1.2 billion for 500,000 tonnes a year of capacity. About how many thousand dollars per annual tonne?", "min": 0, "max": 10, "value": 2.4, "unit": "K", "explanation": "About $2,400 of build cost for each tonne of yearly capacity, before running costs."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A carbon removal buyer asks you how to judge a new plant.", "prompt": "What matters most?", "options": ["How famous the company behind the plant is", "Tonnes measured and stored, not design capacity", "The size of the plant on its website"], "correctIndex": 1, "consequences": ["Fame does not remove CO2.", "You judge delivery, not promises.", "Design figures are not measured removal."], "explanation": "Only measured tonnes count. Both Stratos and Mammoth show how far delivery can lag design."}, "proReasoning": "In carbon removal, the strongest analysts ask for metered results first.", "commonMistake": "Quoting capacity as if it were delivery.", "mentalModel": "Count measured tonnes."}, "invest": {"call": {"kind": "theCall", "situation": "You hold Occidental. Stratos is delayed and over budget.", "prompt": "What do you watch next?", "options": ["Only the design capacity figure", "Nothing, since delays never matter for value", "When it starts and what it actually removes"], "correctIndex": 2, "consequences": ["Capacity is not output.", "Delays raise cost and push back revenue.", "You track the milestones that create value."], "explanation": "Value depends on start-up and measured removal. Cost already rose to $1.2 billion."}, "proReasoning": "Investors track start-up dates and measured output, not announced capacity.", "commonMistake": "Valuing a plant on its nameplate.", "mentalModel": "Track start-up and output."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds direct air capture units.", "prompt": "What do Stratos and Mammoth teach you?", "options": ["Plan for delays and prove output early", "Promise big capacity to win buyers", "Avoid measuring so you cannot miss"], "correctIndex": 0, "consequences": ["You build trust by under-promising.", "Big promises backfire when output lags.", "Buyers pay only for measured tonnes."], "explanation": "Both plants delivered later or less than planned. Early measured output builds trust."}, "proReasoning": "Founders in hard tech earn trust by reporting measured results early and honestly.", "commonMistake": "Selling capacity you have not shown.", "mentalModel": "Under-promise, then measure."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read about a plant built to remove 500,000 tonnes a year.", "prompt": "Is that what it removes?", "options": ["Yes, and it removed far more", "No, that is its design, not measured output", "Yes, every single year from the first day"], "correctIndex": 1, "consequences": ["No measured result was reported.", "Design and delivery are different numbers.", "It was delayed after commissioning."], "explanation": "Stratos is designed for 500,000 tonnes a year but was delayed with no new start date."}, "proReasoning": "Check whether a big number is a design figure or a measured one.", "commonMistake": "Reading capacity as results.", "mentalModel": "Design is not delivery."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:02680616903a$ml$]::text[]),
($ml$ac413ccb-f2ae-5519-a185-2d4cda8ff684$ml$::uuid, $ml$climatetech$ml$, 12, 2, $ml${"id": "climatetech-d12-c2", "title": "Tonnes against the budget", "lessonTitle": "Pulling CO2 from the air", "slot": 2, "type": "connect", "brief": {"headline": "Climeworks' Orca plant, rated at 4,000 tonnes a year, never removed more than 1,000 tonnes net in a year. The world's fossil emissions reached 38.1 billion tonnes in 2025.", "kicker": "Connect day 4 and day 12: removal next to the budget.", "fullText": "Day 4 showed the scale: a record 38.1 billion tonnes of fossil CO2 in 2025, and a 1.5°C budget nearly used up.\n\nDay 12 shows where air capture stands. Mammoth, built for 36,000 tonnes a year, captured 750 tonnes in its first ten months. Orca never topped 1,000 tonnes net in a year. Climeworks now targets $300 a tonne by 2030, up from an earlier $100.", "sources": [{"url": "https://www.swissinfo.ch/eng/climate-solutions/why-swiss-carbon-removal-start-up-climeworks-faces-serious-headwinds/89386618", "label": "SWI swissinfo.ch, why Climeworks faces serious headwinds"}, {"url": "https://globalcarbonbudget.org/fossil-fuel-co2-emissions-hit-record-high-in-2025/", "label": "Global Carbon Budget 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why can air capture not replace cutting emissions any time soon?", "options": ["It does not remove any CO2 at all", "It is already cheaper than cutting emissions", "Its measured tonnes are tiny next to emissions"], "correctIndex": 2, "explanation": "Plants remove hundreds or thousands of tonnes, against 38.1 billion tonnes emitted a year."}, "numbers": {"kind": "numberSense", "prompt": "Orca is rated at 4,000 tonnes a year but never removed more than 1,000 net. At most, what share of its rating?", "min": 0, "max": 100, "value": 25, "unit": "%", "explanation": "At most 25% of its rated capacity in any year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A client wants to rely on air capture instead of cutting its emissions.", "prompt": "What do you advise?", "options": ["Rely fully on air capture from now on", "Skip both, since neither works", "Cut first, use removal for what is left"], "correctIndex": 2, "consequences": ["Measured removal is far too small to rely on.", "Cutting emissions clearly works.", "You match removal to its real scale."], "explanation": "Removal plants deliver small, uncertain tonnes. Cuts must come first."}, "proReasoning": "Good advisers place removal after cuts, sized to what it actually delivers.", "commonMistake": "Letting removal promises delay real cuts.", "mentalModel": "Cut first, remove the rest."}, "invest": {"call": {"kind": "theCall", "situation": "Climeworks raised its 2030 cost target from $100 to $300 a tonne.", "prompt": "What does that tell you?", "options": ["Costs are falling slower than promised", "Air capture is now cheaper than ever", "Nothing about its business outlook"], "correctIndex": 0, "consequences": ["You see the gap between plan and reality.", "A higher target means higher costs.", "Cost is central to the business case."], "explanation": "Tripling the target price signals costs came down far more slowly than expected."}, "proReasoning": "Investors watch revised targets. A tripled price target is a strong signal.", "commonMistake": "Ignoring a revised target because the mission is appealing.", "mentalModel": "Revised targets reveal reality."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to start a carbon removal company.", "prompt": "Which lesson do you take from Climeworks?", "options": ["Skip measuring to move faster", "Design for harsh real conditions from day one", "Build the biggest plant possible, right away"], "correctIndex": 1, "consequences": ["Buyers only pay for measured tonnes.", "Frozen parts in Iceland show conditions matter.", "Scaling before it works multiplies problems."], "explanation": "Ice and snow froze mechanisms at the Iceland plants, and output fell far short."}, "proReasoning": "Hard tech founders test in real conditions before scaling.", "commonMistake": "Scaling a design that has not met real weather.", "mentalModel": "Prove it in the field first."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder whether machines can just suck CO2 out of the air.", "prompt": "What's the honest picture?", "options": ["They already remove most emissions", "They cannot remove any CO2", "They can, but only in very small amounts"], "correctIndex": 2, "consequences": ["They remove thousands of tonnes, not billions.", "They do capture some CO2.", "Real, but tiny next to emissions."], "explanation": "Orca never topped 1,000 tonnes net a year, against 38.1 billion tonnes emitted."}, "proReasoning": "Compare a technology's tonnes with the size of the problem.", "commonMistake": "Assuming a working technology is a working solution at scale.", "mentalModel": "Works is not the same as scales."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:477e5c64f9fb$ml$]::text[]),
($ml$7e677e57-1104-572d-b233-a0c2983afe47$ml$::uuid, $ml$climatetech$ml$, 12, 3, $ml${"id": "climatetech-d12-c3", "title": "Signing a removal contract", "lessonTitle": "Pulling CO2 from the air", "slot": 3, "type": "decide", "brief": {"headline": "You buy carbon removal for a tech company. A supplier offers a big discount for paying upfront. Climeworks' Mammoth, built for 36,000 tonnes a year, captured 750 tonnes in ten months.", "kicker": "Decide how to pay for removal you cannot see yet.", "fullText": "In May 2025, Climeworks cut 106 of its 498 jobs. Ice and snow had frozen mechanisms at its Iceland plants, and costs fell more slowly than expected. It now targets $300 a tonne by 2030, up from $100.\n\nA planned freeze on $500 million in US support for a Louisiana plant added uncertainty. Your board wants removal on the books, but only tonnes that are real.", "sources": [{"url": "https://www.swissinfo.ch/eng/climate-solutions/why-swiss-carbon-removal-start-up-climeworks-faces-serious-headwinds/89386618", "label": "SWI swissinfo.ch, why Climeworks faces serious headwinds"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is this a measured result or a promise?", "buckets": ["Measured", "Promise"], "items": [{"text": "CO2 metered into storage", "bucket": 0}, {"text": "Tonnes verified as permanently stored", "bucket": 0}, {"text": "A plant's design capacity", "bucket": 1}, {"text": "A target price for 2030", "bucket": 1}, {"text": "Credits sold for future delivery", "bucket": 1}], "explanation": "Only metered, verified tonnes are results. Capacity, targets and future credits are promises."}, "numbers": {"kind": "numberSense", "prompt": "Climeworks raised its 2030 target from $100 to $300 a tonne. How many times higher?", "min": 0, "max": 10, "value": 3, "unit": "x", "explanation": "Three times higher, a sign costs fell slower than planned."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the buyer drafting the contract.", "prompt": "What payment terms do you push for?", "options": ["Pay as verified tonnes are delivered", "Pay everything upfront for the discount", "Pay only after 2030, no matter what"], "correctIndex": 0, "consequences": ["You pay for results, not promises.", "Upfront cash is at risk if output lags.", "Suppliers need some revenue to build."], "explanation": "Mammoth captured 750 tonnes against a 36,000-tonne design. Pay for what is delivered."}, "proReasoning": "Good buyers tie payment to verified delivery, especially for unproven technology.", "commonMistake": "Taking a discount that shifts all delivery risk onto you.", "mentalModel": "Pay for delivered tonnes."}, "invest": {"call": {"kind": "theCall", "situation": "Your CFO sees the upfront discount as a good deal.", "prompt": "What risk does the discount hide?", "options": ["Prices will surely fall further", "Tonnes may arrive late, or never", "There is no risk with a discount"], "correctIndex": 1, "consequences": ["The 2030 target rose, not fell.", "You price in delivery risk.", "Mammoth shows delivery can lag badly."], "explanation": "A supplier that cut 106 jobs and tripled its cost target carries real delivery risk."}, "proReasoning": "Investors see an upfront discount as payment for taking on delivery risk.", "commonMistake": "Judging a deal by price alone.", "mentalModel": "A discount is a risk premium."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the removal supplier. Buyers want to pay only on delivery.", "prompt": "How do you fund building the plant?", "options": ["Insist on full payment years in advance", "Build with no customers at all", "Partial upfront payment tied to milestones"], "correctIndex": 2, "consequences": ["After recent misses, buyers will refuse.", "Without customers, funding dries up.", "You share risk in a way buyers can accept."], "explanation": "Milestone payments balance the supplier's need for cash with the buyer's need for proof."}, "proReasoning": "Founders bridge the trust gap with milestones buyers can verify.", "commonMistake": "Demanding full upfront cash in a market that has been burned.", "mentalModel": "Tie cash to milestones."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why buyers pay for carbon removal in advance at all.", "prompt": "Why might they?", "options": ["To help new plants get built at all", "Because removal is already plentiful", "Because it is required by every law"], "correctIndex": 0, "consequences": ["Early buyers fund the first plants.", "Measured removal is still tiny.", "Most removal purchases are voluntary."], "explanation": "Without early buyers, new plants struggle to get built. But early money carries risk."}, "proReasoning": "Early buyers fund a new industry, and take on its risks.", "commonMistake": "Thinking advance purchases are risk-free.", "mentalModel": "Early money carries early risk."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e06062b44068$ml$]::text[]),
($ml$90628389-2cf4-5b1e-820d-4a09d4c57bb8$ml$::uuid, $ml$climatetech$ml$, 13, 1, $ml${"id": "climatetech-d13-c1", "title": "Sixty-four new plans", "lessonTitle": "The deal almost every country signed", "slot": 1, "type": "apply", "brief": {"headline": "A UN report in October 2025 counted 64 new national climate plans. Fully carried out, they would cut emissions about 17% below 2019 levels by 2035, with a peak before 2030.", "kicker": "Apply the rule: do the national plans add up?", "fullText": "Under the Paris Agreement, each country writes its own plan, called a nationally determined contribution, every five years. The UN synthesis report counted 64 new plans ahead of COP30 in Belém. 89% of those countries set economy-wide targets.\n\nUN climate chief Simon Stiell put the expected decline at about 10% on a broader count. To keep 1.5°C in reach, the UN says emissions must fall 43% by 2030.", "sources": [{"url": "https://news.un.org/en/story/2025/10/1166204", "label": "UN News, 2025 NDC synthesis report"}, {"url": "https://www.unfccc.int/process-and-meetings/the-paris-agreement", "label": "UNFCCC, The Paris Agreement"}]}, "evidence": {"kind": "multipleChoice", "prompt": "New plans would cut about 17% by 2035. How does that compare with what 1.5°C needs?", "options": ["Far short: 1.5°C needs 43% by 2030", "On track for 1.5°C with room to spare", "Above target, so plans can be weaker"], "correctIndex": 0, "explanation": "A 17% cut by 2035 is far below the 43% cut by 2030 that the UN says 1.5°C requires."}, "numbers": {"kind": "numberSense", "prompt": "64 new plans out of about 195 parties. About what share had submitted?", "min": 0, "max": 100, "value": 33, "unit": "%", "explanation": "About a third. Many countries had not yet filed new plans when the report came out."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A climate policy NGO asks what the 2025 NDC report tells us.", "prompt": "What is the key takeaway?", "options": ["The world is now fully on a 1.5°C path", "Plans are irrelevant, since they are voluntary", "Plans move the right way but far too little"], "correctIndex": 2, "consequences": ["A 17% cut is far from the 43% needed.", "National plans are the core of Paris.", "You give direction and gap in one line."], "explanation": "Emissions would peak before 2030 and fall about 17% by 2035, well short of 1.5°C."}, "proReasoning": "Good policy analysts report both direction and size of the gap.", "commonMistake": "Calling progress success, or calling a gap failure, without both numbers.", "mentalModel": "Direction plus gap."}, "invest": {"call": {"kind": "theCall", "situation": "You set long-term assumptions for a clean energy fund.", "prompt": "What does the report suggest?", "options": ["More ambition will be needed in the next plans", "Policies will now get weaker in every country", "Nothing will change for a decade"], "correctIndex": 0, "consequences": ["You expect pressure for stronger plans.", "Plans are meant to get stronger each round.", "Paris runs on five-year cycles."], "explanation": "Each new plan is meant to be stronger, and the gap to 1.5°C stays large."}, "proReasoning": "Investors read the ratchet: a big gap means pressure for stronger plans every five years.", "commonMistake": "Assuming today's plans are the final word.", "mentalModel": "Gaps create pressure for the next round."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells tools that help governments track progress on their NDCs.", "prompt": "What does the report mean for you?", "options": ["Only a few countries will ever report", "More countries need tracking as plans grow", "Demand ends once plans are filed"], "correctIndex": 1, "consequences": ["89% set economy-wide targets to track.", "Plans need tracking long after filing.", "Countries report on progress, not just filing."], "explanation": "Countries report progress under a shared transparency framework, which needs data every year."}, "proReasoning": "Founders who serve governments look at reporting cycles, not one-off filings.", "commonMistake": "Treating a filing deadline as the end of demand.", "mentalModel": "Plans create ongoing reporting."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that new climate plans would cut emissions 17% by 2035.", "prompt": "Is that enough?", "options": ["Yes, it meets the Paris goals", "It means emissions will rise", "No, 1.5°C needs much deeper cuts"], "correctIndex": 2, "consequences": ["It falls well short of the goals.", "The plans point to a peak before 2030.", "The UN says 43% by 2030 for 1.5°C."], "explanation": "A 17% cut by 2035 is far less than the 43% cut by 2030 needed for 1.5°C."}, "proReasoning": "Compare a pledge with the target it is meant to reach.", "commonMistake": "Judging a cut as big without the target next to it.", "mentalModel": "Compare pledge with need."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d77701a41940$ml$]::text[]),
($ml$d07dc11c-2744-56f7-946f-dc95147f681c$ml$::uuid, $ml$climatetech$ml$, 13, 2, $ml${"id": "climatetech-d13-c2", "title": "A ratchet against a clock", "lessonTitle": "The deal almost every country signed", "slot": 2, "type": "connect", "brief": {"headline": "Paris asks countries for stronger plans every five years. Meanwhile, the 1.5°C carbon budget is about 170 billion tonnes, about four years of 2025 emissions.", "kicker": "Connect day 4 and day 13: a five-year cycle against a short budget.", "fullText": "The Paris Agreement, adopted by 195 parties in 2015, entered into force in November 2016. Each country sets its own plan on a five-year cycle meant to grow more ambitious each time. Countries began reporting progress under a shared framework in 2024.\n\nDay 4 showed the clock: the Global Carbon Budget calls the 1.5°C budget virtually exhausted. A plan updated every five years is slow next to a budget measured in about four.", "sources": [{"url": "https://www.unfccc.int/process-and-meetings/the-paris-agreement", "label": "UNFCCC, The Paris Agreement"}, {"url": "https://globalcarbonbudget.org/fossil-fuel-co2-emissions-hit-record-high-in-2025/", "label": "Global Carbon Budget 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put these Paris milestones in order.", "steps": ["195 parties adopt the agreement in 2015", "It enters into force in November 2016", "Countries begin progress reports in 2024", "Countries file new plans for 2035 in 2025", "The next round of plans is due five years later"], "explanation": "Adopt, enter into force, report, update every five years. The cycle is built in."}, "numbers": {"kind": "numberSense", "prompt": "By what percent must emissions fall by 2030 to keep 1.5°C in reach, according to the UN?", "min": 0, "max": 100, "value": 43, "unit": "%", "explanation": "About 43% by 2030, within a single five-year planning cycle."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A think tank asks what tension sits at the heart of Paris.", "prompt": "How do you describe it?", "options": ["Slow five-year cycles against a fast budget", "Too many countries signed up at the same time", "The goal changes every single year"], "correctIndex": 0, "consequences": ["You name the timing mismatch.", "Broad participation is a strength of the deal.", "The goal has stayed the same since 2015."], "explanation": "Plans update every five years, while the 1.5°C budget lasts about four years at 2025 emissions."}, "proReasoning": "Spotting a timing mismatch between a process and a limit is a sharp analytical skill.", "commonMistake": "Criticizing the deal without naming the specific tension.", "mentalModel": "Name the timing mismatch."}, "invest": {"call": {"kind": "theCall", "situation": "You think about when climate policy might tighten sharply.", "prompt": "What timing matters?", "options": ["There is no schedule at all", "Each new five-year round of national plans", "Only the original 2015 signing date in Paris"], "correctIndex": 1, "consequences": ["Paris runs on a set five-year cycle.", "You watch the scheduled ratchet points.", "That date is long past."], "explanation": "New plans come every five years, each meant to be stronger, so those rounds are policy moments."}, "proReasoning": "Investors mark the ratchet dates. Policy shifts cluster around new plan rounds.", "commonMistake": "Ignoring the built-in schedule of climate policy.", "mentalModel": "Watch the ratchet dates."}, "build_startup": {"call": {"kind": "theCall", "situation": "You plan your startup's fundraising around climate policy.", "prompt": "What should you expect?", "options": ["Policy will never affect your market at all", "All policy changes happen at once", "Demand spikes around each round of new plans"], "correctIndex": 2, "consequences": ["Climate markets depend on policy.", "Changes come in five-year rounds.", "You time launches to policy moments."], "explanation": "New national plans arrive every five years and often bring new targets and spending."}, "proReasoning": "Founders who know the policy calendar time launches and raises to it.", "commonMistake": "Ignoring the calendar that shapes your buyers.", "mentalModel": "Know the policy calendar."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why Paris asks for new plans only every five years.", "prompt": "What is the trade-off?", "options": ["Time to plan, but slow against the budget", "It is faster than any other approach", "It means plans can never change"], "correctIndex": 0, "consequences": ["You see both the benefit and the cost.", "The budget may run out within one cycle.", "Plans are meant to be updated."], "explanation": "Five years gives countries time to plan, but the 1.5°C budget is about four years."}, "proReasoning": "Every process design trades speed against stability.", "commonMistake": "Assuming a cycle length was chosen for speed.", "mentalModel": "Cycles trade speed for stability."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2b113c95123b$ml$]::text[]),
($ml$a28239dc-917a-5687-a94a-2224286f74dc$ml$::uuid, $ml$climatetech$ml$, 13, 3, $ml${"id": "climatetech-d13-c3", "title": "Writing a national plan", "lessonTitle": "The deal almost every country signed", "slot": 3, "type": "decide", "brief": {"headline": "You advise a mid-sized country writing its next climate plan under Paris. Its leaders ask what the agreement requires and what they decide for themselves.", "kicker": "Decide what your country controls under Paris.", "fullText": "The Paris Agreement, adopted by 195 parties, aims to hold warming well below 2°C and pursue 1.5°C. Each country writes its own target and plan, its nationally determined contribution, every five years.\n\nTargets are national choices, not set by the UN. Each new plan is meant to be stronger than the last, and countries report progress under a shared transparency framework that began in 2024.", "sources": [{"url": "https://www.unfccc.int/process-and-meetings/the-paris-agreement", "label": "UNFCCC, The Paris Agreement"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does the country decide this, or is it set by the agreement?", "buckets": ["Country decides", "Set by Paris"], "items": [{"text": "How deep its emission cut is", "bucket": 0}, {"text": "Which sectors it cuts first", "bucket": 0}, {"text": "The well below 2°C goal", "bucket": 1}, {"text": "A new plan every five years", "bucket": 1}, {"text": "Reporting under a shared framework", "bucket": 1}], "explanation": "Paris sets the goal, the cycle and the reporting. Each country chooses its own targets and methods."}, "numbers": {"kind": "numberSense", "prompt": "How many parties adopted the Paris Agreement in December 2015?", "min": 0, "max": 250, "value": 195, "unit": "parties", "explanation": "195 parties, nearly every country in the world."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a junior adviser. The minister asks if the UN will set your target.", "prompt": "What do you answer?", "options": ["No, and we never need to update it", "No, we set it; Paris asks it to grow", "Yes, the UN sets each country's target"], "correctIndex": 1, "consequences": ["Plans are renewed every five years.", "You describe the national choice and the ratchet.", "Targets are national choices."], "explanation": "Targets are national choices, renewed every five years and meant to get stronger."}, "proReasoning": "Advisers who know where national choice ends and treaty duty starts give clear options.", "commonMistake": "Telling a minister the UN decides their target.", "mentalModel": "Separate national choice from treaty duty."}, "invest": {"call": {"kind": "theCall", "situation": "You are judging how credible this country's new climate plan is.", "prompt": "What do you check?", "options": ["Only whether a headline target was announced", "Whether the UN approved the number", "Whether policies exist to deliver the target"], "correctIndex": 2, "consequences": ["Announcements are cheap without policies.", "The UN does not approve targets.", "You test delivery, not just the promise."], "explanation": "Each country sets its own target, so credibility depends on its own policies."}, "proReasoning": "Investors test national plans against the policies meant to deliver them.", "commonMistake": "Taking a headline target at face value.", "mentalModel": "Check the policies behind the target."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup could help this country plan its sector targets.", "prompt": "What is your opening?", "options": ["Help pick which sectors to cut, and how", "Help it convince the UN to set targets", "Help it skip the reporting framework"], "correctIndex": 0, "consequences": ["You serve the choices the country owns.", "The UN does not set national targets.", "Reporting is part of the agreement."], "explanation": "Countries decide their own targets and methods, which is where planning help is needed."}, "proReasoning": "Founders serving governments focus on the decisions governments actually own.", "commonMistake": "Selling help with something the treaty already fixes.", "mentalModel": "Serve the choices they own."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder how one deal can work for 195 very different countries.", "prompt": "What's the trick?", "options": ["Only rich countries have any duties", "One shared goal, but each sets its own plan", "Every country gets exactly the same target"], "correctIndex": 1, "consequences": ["Every party writes a plan.", "Flexibility let nearly everyone sign.", "Targets differ by country."], "explanation": "The goal is shared, but every country sets its own plan."}, "proReasoning": "Shared goals with national choices let very different countries join one deal.", "commonMistake": "Assuming one global target was imposed on everyone.", "mentalModel": "Shared goal, national plans."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:eb7bb8457dd1$ml$]::text[]),
($ml$3c10e271-9fbb-59f8-a034-1c8d1442f8c9$ml$::uuid, $ml$climatetech$ml$, 14, 1, $ml${"id": "climatetech-d14-c1", "title": "The fund that pays for damage", "lessonTitle": "The $300 billion promise", "slot": 1, "type": "apply", "brief": {"headline": "In April 2025, the UN loss and damage fund approved a first $250 million phase of grants for climate-hit countries. It had received pledges of $768.4 million, but only $321 million paid in.", "kicker": "Apply the rule: who pays, and how much actually arrives?", "fullText": "The Fund for Responding to Loss and Damage adopted the plan at its board meeting in Bridgetown, Barbados, on April 8 to 10. Eligible countries can receive grants of $5 million to $20 million to strengthen their response to climate disasters. At least half goes to small island states and least developed countries.\n\nOne estimate puts developing countries' loss and damage needs at about $395 billion in 2025.", "sources": [{"url": "https://cvfv20.org/250-million-approved-for-initial-phase-of-loss-and-damage-fund/", "label": "CVF-V20, $250 million for the loss and damage fund"}, {"url": "https://iisd.org/articles/insight/baku-conference-sets-new-collective-climate-finance-goal", "label": "IISD, Baku conference sets new climate finance goal"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The first phase was $250 million.", "Grants range from $5 million to $20 million.", "All $768 million pledged had been paid in."], "fakeIndex": 2, "explanation": "Only $321 million of the $768.4 million pledged had been paid in."}, "numbers": {"kind": "numberSense", "prompt": "$321 million paid in out of $768.4 million pledged. About what share?", "min": 0, "max": 100, "value": 42, "unit": "%", "explanation": "About 42%. Pledges are not money in the bank."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An NGO asks how to describe the loss and damage fund's resources.", "prompt": "Which description is accurate?", "options": ["$768m pledged, but only $321m paid in", "Nearly $800 million ready to spend now", "$395 billion available for 2025"], "correctIndex": 0, "consequences": ["You separate pledges from cash.", "Less than half the pledges had arrived.", "That is an estimate of need, not money."], "explanation": "Pledges reached $768.4 million; $321 million had been paid in."}, "proReasoning": "In climate finance, always separate pledged, paid and spent.", "commonMistake": "Quoting pledges as if they were cash.", "mentalModel": "Pledged, paid, spent: three numbers."}, "invest": {"call": {"kind": "theCall", "situation": "You compare $250 million in grants with $395 billion of estimated need.", "prompt": "What does the gap suggest?", "options": ["Losses will shrink without action", "Public funds cover a sliver of the need", "The need is fully covered already"], "correctIndex": 1, "consequences": ["Climate losses are rising.", "You see room for other finance and insurance.", "$250 million is far below $395 billion."], "explanation": "$250 million is a tiny share of an estimated $395 billion in need."}, "proReasoning": "Investors read big gaps as openings for insurance, risk pools and private capital.", "commonMistake": "Treating a public fund as the full answer.", "mentalModel": "Compare the fund with the need."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds early warning systems for flood-prone countries.", "prompt": "How can this fund matter to you?", "options": ["It pays companies directly for any product", "It only funds rebuilding after disasters", "Grants of $5m to $20m can buy disaster tools"], "correctIndex": 2, "consequences": ["It grants to countries, not to companies.", "It funds stronger national responses too.", "Countries can spend grants on preparedness."], "explanation": "Grants strengthen national responses to climate disasters, which can include warning systems."}, "proReasoning": "Founders track where public money flows, then sell to the countries that receive it.", "commonMistake": "Expecting a public fund to pay vendors directly.", "mentalModel": "Sell to whoever receives the grant."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear about a fund that pays for climate damage.", "prompt": "How big is it compared with the need?", "options": ["Tiny: $250m against $395bn in need", "About the same size as the need", "Larger than the need"], "correctIndex": 0, "consequences": ["The first phase is a fraction of the need.", "The need is over a thousand times larger.", "The need dwarfs the fund."], "explanation": "The first phase is $250 million, against an estimated $395 billion of need in 2025."}, "proReasoning": "Put any fund next to the need it addresses.", "commonMistake": "Being impressed by a big number without its comparison.", "mentalModel": "Size the fund against the need."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7149fe661ece$ml$]::text[]),
($ml$569f93be-289c-5787-8057-4504749d7535$ml$::uuid, $ml$climatetech$ml$, 14, 2, $ml${"id": "climatetech-d14-c2", "title": "Who should pay, and who emits", "lessonTitle": "The $300 billion promise", "slot": 2, "type": "connect", "brief": {"headline": "At COP29, developed countries agreed to lead a goal of $300 billion a year for developing countries by 2035. Developing countries, including China, were only encouraged to contribute.", "kicker": "Connect day 3 and day 14: today's biggest emitter is not a required payer.", "fullText": "The Baku deal set at least $300 billion a year by 2035, led by developed countries, and called for $1.3 trillion a year from all sources. Developed countries wanted more contributors, including those \"in a position to contribute.\"\n\nDay 3 showed that China emits about 32% of fossil CO2, more than the US, India and the EU combined. Under UN rules it is still a developing country, so its contributions are voluntary.", "sources": [{"url": "https://iisd.org/articles/insight/baku-conference-sets-new-collective-climate-finance-goal", "label": "IISD, Baku conference sets new climate finance goal"}, {"url": "https://www.cger.nies.go.jp/gcp/pdf/20251113/CarbonBudget2025_CICERO_press_E.pdf", "label": "CICERO, Global Carbon Budget 2025 release"}]}, "evidence": {"kind": "faceOff", "prompt": "Under the COP29 deal, who must take the lead on the $300 billion?", "left": {"name": "Developed countries", "note": "The US, EU members, Japan and others"}, "right": {"name": "China", "note": "Largest emitter, counted as developing"}, "correctIndex": 0, "explanation": "Developed countries take the lead. Developing countries, China included, are encouraged to contribute voluntarily."}, "numbers": {"kind": "numberSense", "prompt": "The deal called for $1.3 trillion a year, with $300 billion as the core goal. About how many times larger?", "min": 0, "max": 10, "value": 4.3, "unit": "x", "explanation": "About 4.3 times. The core goal is a fraction of the wider call."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A foreign ministry asks why finance talks are so hard.", "prompt": "What is the core tension?", "options": ["Nobody thinks finance is needed", "Who pays is set by old categories", "Everyone agrees on who should pay"], "correctIndex": 1, "consequences": ["All sides agree finance is needed.", "You name the clash between categories and emissions.", "Developed countries wanted more contributors."], "explanation": "China emits 32% but is counted as developing, so its contributions are voluntary."}, "proReasoning": "Diplomats who understand why categories matter can explain deadlocks clearly.", "commonMistake": "Blaming one side without explaining the category problem.", "mentalModel": "Categories decide who pays."}, "invest": {"call": {"kind": "theCall", "situation": "You assess how much climate finance will flow to developing markets.", "prompt": "Which figure is firmer?", "options": ["The $1.3 trillion call from all sources combined", "Both are equally binding pledges", "The $300 billion goal led by developed countries"], "correctIndex": 2, "consequences": ["The $1.3 trillion is a call, not a pledge.", "They differ in strength.", "You rely on the firmer core goal."], "explanation": "The $300 billion is the core goal; the $1.3 trillion figure is a broader call."}, "proReasoning": "Investors weight firm commitments over aspirational calls.", "commonMistake": "Treating a call to action as a funded pledge.", "mentalModel": "Weight firm goals over calls."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup helps developing countries plan climate projects.", "prompt": "What should you plan around?", "options": ["Firm $300bn goal, uncertain extra from others", "A guaranteed $1.3 trillion every single year", "No finance at all"], "correctIndex": 0, "consequences": ["You plan on the firm number and treat the rest as upside.", "The $1.3 trillion is not guaranteed.", "A $300 billion goal was agreed."], "explanation": "Developed countries lead the $300 billion; contributions from others are voluntary."}, "proReasoning": "Founders plan on the firm number and treat the rest as upside.", "commonMistake": "Building a plan on the most optimistic figure.", "mentalModel": "Plan on the firm number."}, "curiosity": {"call": {"kind": "theCall", "situation": "You learn China is not required to pay into climate finance.", "prompt": "Why not?", "options": ["It already pays more than anyone", "UN rules still class it as developing", "It emits less than most countries"], "correctIndex": 1, "consequences": ["Its contributions are voluntary.", "The category dates from decades ago.", "It emits about 32%, the most."], "explanation": "China is counted as developing under UN rules, so it is only encouraged to contribute."}, "proReasoning": "Old categories can lag behind today's emissions.", "commonMistake": "Assuming obligations always follow current emissions.", "mentalModel": "Categories can lag reality."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6ab26630074d$ml$]::text[]),
($ml$6781d492-e01e-5a12-87b4-f322ea6f32bb$ml$::uuid, $ml$climatetech$ml$, 14, 3, $ml${"id": "climatetech-d14-c3", "title": "Spending the new goal", "lessonTitle": "The $300 billion promise", "slot": 3, "type": "decide", "brief": {"headline": "You plan climate lending at a development bank. COP29 set a goal of at least $300 billion a year for developing countries by 2035, replacing the old $100 billion goal.", "kicker": "Decide where your bank's share should go first.", "fullText": "Developed countries are to take the lead, with developing countries encouraged to contribute voluntarily. The deal also called on all actors to scale finance to at least $1.3 trillion a year by 2035.\n\nDeveloping countries had called for a higher amount. Your bank can lend for projects that cut emissions, or for projects that help countries adapt to damage already happening.", "sources": [{"url": "https://iisd.org/articles/insight/baku-conference-sets-new-collective-climate-finance-goal", "label": "IISD, Baku conference sets new climate finance goal"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did the $300 billion goal replace?", "options": ["Nothing, it is the first finance goal", "The older goal of $100 billion a year", "A $1 trillion goal set in Paris"], "correctIndex": 1, "explanation": "It replaced the old $100 billion a year goal."}, "numbers": {"kind": "numberSense", "prompt": "The new goal is $300 billion a year; the old one was $100 billion. How many times larger?", "min": 0, "max": 10, "value": 3, "unit": "x", "explanation": "Three times larger, though developing countries asked for more."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a new analyst at the bank. Your boss asks what the goal means for your team.", "prompt": "What do you say?", "options": ["A one-time payment next year", "No change, since the goal is voluntary", "A larger pipeline over a decade to 2035"], "correctIndex": 2, "consequences": ["It is a yearly goal by 2035.", "Developed countries agreed to lead it.", "You frame it as growing, multi-year demand."], "explanation": "The goal is at least $300 billion a year by 2035, built up over a decade."}, "proReasoning": "Translating a global goal into your team's pipeline shows business sense.", "commonMistake": "Reading a yearly goal as a one-off.", "mentalModel": "Turn a goal into a pipeline."}, "invest": {"call": {"kind": "theCall", "situation": "Your bank wants loans that attract private money alongside.", "prompt": "What fits the deal's wider call?", "options": ["Projects that pull in private co-investors", "Grants that use only public money and nothing else", "Loans to developed countries only"], "correctIndex": 0, "consequences": ["You help reach the $1.3 trillion call.", "Public money alone will not reach $1.3 trillion.", "The goal is for developing countries."], "explanation": "The deal calls for $1.3 trillion from public and private sources, so pulling in private money matters."}, "proReasoning": "Development banks stretch public money by bringing private investors in.", "commonMistake": "Spending public money where private money would have come anyway.", "mentalModel": "Use public money to pull in private."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers solar mini-grids in developing countries.", "prompt": "How does the new goal help you?", "options": ["Nothing, it only funds governments", "More lenders seeking projects like yours", "Free money with no conditions"], "correctIndex": 1, "consequences": ["Banks lend to projects and companies too.", "Growing finance needs good projects.", "Development finance comes with terms."], "explanation": "A tripled goal means more finance chasing investable projects."}, "proReasoning": "When finance grows, founders with ready projects win.", "commonMistake": "Expecting climate finance to come without conditions.", "mentalModel": "Have projects ready when money grows."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder whether $300 billion a year is a lot.", "prompt": "How to judge it?", "options": ["Far more than anyone had requested at the talks", "Too small to matter at all", "Triple the old goal, below what was asked"], "correctIndex": 2, "consequences": ["Developing countries asked for more.", "It triples the previous goal.", "You hold both comparisons."], "explanation": "It triples the old $100 billion goal, but developing countries had called for more."}, "proReasoning": "Judge a number against what came before and what was asked.", "commonMistake": "Calling a number big or small without a reference.", "mentalModel": "Compare with before and with the ask."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e78d1295b8b7$ml$]::text[]),
($ml$fcb15b35-d168-5c3f-8bab-70150a0cfbc1$ml$::uuid, $ml$climatetech$ml$, 15, 1, $ml${"id": "climatetech-d15-c1", "title": "States that stayed in", "lessonTitle": "The US leaves Paris, again", "slot": 1, "type": "apply", "brief": {"headline": "When the US first moved to leave Paris in 2017, governors formed the US Climate Alliance. By April 2026 it had 25 members, representing about 55% of Americans and 60% of the US economy.", "kicker": "Apply the rule: who keeps commitments when a government drops them?", "fullText": "The Alliance was founded on June 1, 2017, after President Trump announced his first withdrawal. Its members are 23 states and two territories, Puerto Rico and Guam. Virginia rejoined in April 2026.\n\nMembers pledged to cut economy-wide emissions 26 to 28% from 2005 levels by 2025. The US formally left the Paris Agreement for the second time on January 27, 2026.", "sources": [{"url": "https://en.wikipedia.org/wiki/United_States_Climate_Alliance", "label": "Wikipedia, United States Climate Alliance"}, {"url": "https://www.eenews.net/articles/so-long-paris-us-officially-leaves-landmark-climate-pact/", "label": "E&E News, US officially leaves the Paris pact"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is this a federal or a state-level climate action?", "buckets": ["Federal", "State level"], "items": [{"text": "Leaving the Paris Agreement", "bucket": 0}, {"text": "Notifying the UN of withdrawal", "bucket": 0}, {"text": "Joining the US Climate Alliance", "bucket": 1}, {"text": "A 26 to 28% cut from 2005 levels", "bucket": 1}, {"text": "Virginia rejoining in 2026", "bucket": 1}], "explanation": "Leaving Paris is a federal act. The Alliance and its targets are state commitments."}, "numbers": {"kind": "numberSense", "prompt": "About what share of the US economy do Climate Alliance members represent?", "min": 0, "max": 100, "value": 60, "unit": "%", "explanation": "About 60% of the US economy, and about 55% of the population."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A European client asks if US climate policy ended when the US left Paris.", "prompt": "What do you answer?", "options": ["Yes, states are banned from acting", "No, states with 60% of GDP kept going", "Yes, all US climate policy stopped"], "correctIndex": 1, "consequences": ["States set their own climate policies.", "You describe the split between levels of government.", "Alliance states kept their own targets."], "explanation": "States making up about 60% of the economy stayed committed through the Alliance."}, "proReasoning": "Explaining federal versus state roles is essential for anyone advising on US climate policy.", "commonMistake": "Treating the federal stance as the whole country's.", "mentalModel": "Separate federal from state."}, "invest": {"call": {"kind": "theCall", "situation": "You plan US clean energy investments after the withdrawal.", "prompt": "Where do you focus?", "options": ["Nowhere in the US for the time being", "Only federal programs", "States still pursuing climate targets"], "correctIndex": 2, "consequences": ["States with 60% of GDP kept targets.", "Federal support is shrinking.", "You follow the policy that still exists."], "explanation": "Alliance members kept climate goals, so state policy now drives much US demand."}, "proReasoning": "Investors map policy by state when federal policy retreats.", "commonMistake": "Writing off a whole country over one level of government.", "mentalModel": "Map policy by state."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your US climate startup lost hope of federal support.", "prompt": "What is your best move?", "options": ["Sell to Alliance states and their utilities", "Leave the US market entirely for a while", "Wait for the next federal change"], "correctIndex": 0, "consequences": ["You go where commitments remain.", "States with most of the economy still buy.", "Waiting stalls the company."], "explanation": "States with about 55% of Americans kept their targets."}, "proReasoning": "Founders follow commitments to the level of government that keeps them.", "commonMistake": "Abandoning a market that is only partly closed.", "mentalModel": "Follow the commitments that remain."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder whether the US really quit climate action.", "prompt": "What's more accurate?", "options": ["The US never joined Paris at all", "Federal exit, but many states kept going", "Every state followed the federal exit"], "correctIndex": 1, "consequences": ["It joined, then left twice.", "You see both levels of government.", "25 jurisdictions stayed in the Alliance."], "explanation": "The federal government left Paris, while Alliance states kept their goals."}, "proReasoning": "In federal countries, the national position is not the whole story.", "commonMistake": "Assuming one government speaks for every state.", "mentalModel": "Look below the national level."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ce91147aa0b1$ml$]::text[]),
($ml$b51bca5d-2c6b-51c9-97da-7e9f7235f283$ml$::uuid, $ml$climatetech$ml$, 15, 2, $ml${"id": "climatetech-d15-c2", "title": "One year to leave", "lessonTitle": "The US leaves Paris, again", "slot": 2, "type": "connect", "brief": {"headline": "The US announced its Paris withdrawal on January 20, 2025, and notified the UN a week later. Under the agreement's rules, the exit took effect one year after notice, on January 27, 2026.", "kicker": "Connect day 13 and day 15: Paris has rules for leaving, too.", "fullText": "Day 13 showed how Paris works: 195 parties, national plans and a five-year cycle. It also sets how a country leaves: a withdrawal takes effect one year after the UN is notified.\n\nThe US is the only country to quit the pact twice; it also left during Trump's first term. The agreement counted 194 parties as of January 27, 2026, and the US is now one of the few countries without a climate pollution reduction goal.", "sources": [{"url": "https://www.eenews.net/articles/so-long-paris-us-officially-leaves-landmark-climate-pact/", "label": "E&E News, US officially leaves the Paris pact"}, {"url": "https://www.unfccc.int/process-and-meetings/the-paris-agreement", "label": "UNFCCC, The Paris Agreement"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the US exit in order.", "steps": ["Trump announces the exit on January 20, 2025", "The US notifies the UN a week later", "The one-year notice period runs", "The exit takes effect on January 27, 2026", "Paris counts 194 parties"], "explanation": "Announce, notify, wait a year, exit. The rules are part of the agreement itself."}, "numbers": {"kind": "numberSense", "prompt": "How many months after notice does a Paris withdrawal take effect?", "min": 0, "max": 36, "value": 12, "unit": "months", "explanation": "Twelve months. Notice in January 2025 meant exit in January 2026."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A client asked in mid-2025 whether the US was still in Paris.", "prompt": "What was the right answer then?", "options": ["No, it left the day it was announced", "It was never a party to Paris", "Yes, until the notice period ended in 2026"], "correctIndex": 2, "consequences": ["Exit only took effect a year after notice.", "The US was a party until 2026.", "You know the treaty's own timing rules."], "explanation": "Withdrawal takes effect one year after notice, so the US stayed a party until January 27, 2026."}, "proReasoning": "Precision on treaty timing matters when advising clients on legal status.", "commonMistake": "Treating an announcement as the legal exit.", "mentalModel": "Announcement is not exit."}, "invest": {"call": {"kind": "theCall", "situation": "You track policy risk in US-linked climate assets.", "prompt": "What did the one-year notice period give markets?", "options": ["A known date to plan around", "A sudden exit with no warning", "A chance the exit was illegal"], "correctIndex": 0, "consequences": ["You use the known date to adjust.", "The rule built in a full year of notice.", "The process followed the treaty."], "explanation": "The exit date was fixed by the treaty a year in advance."}, "proReasoning": "Known policy dates let investors adjust gradually rather than react to surprises.", "commonMistake": "Ignoring treaty timelines when modeling policy risk.", "mentalModel": "Use known dates."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells to US federal climate programs.", "prompt": "What did the notice year allow you to do?", "options": ["Raise prices on federal contracts", "Shift toward state and private buyers", "Ignore it, since nothing changed"], "correctIndex": 1, "consequences": ["Higher prices do not offset lost programs.", "You used the year to diversify.", "Federal climate policy did change."], "explanation": "A year's notice gave time to move toward buyers whose commitments stayed."}, "proReasoning": "Founders use warning periods to diversify before a customer type disappears.", "commonMistake": "Doing nothing during a known transition.", "mentalModel": "Use the warning to diversify."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why leaving Paris takes a year.", "prompt": "Why build in a delay?", "options": ["To stop any country from leaving", "Because the UN must approve it", "To make exits orderly, not sudden"], "correctIndex": 2, "consequences": ["Countries can leave, as the US did.", "No approval is needed, only notice.", "A delay gives everyone time to adjust."], "explanation": "A withdrawal takes effect one year after the UN is notified."}, "proReasoning": "Treaties often build in exit delays to keep changes orderly.", "commonMistake": "Thinking leaving a treaty is instant.", "mentalModel": "Exits come with notice periods."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7ac14dd9578b$ml$]::text[]),
($ml$d21db2df-0ce5-5044-87c2-f7374192c333$ml$::uuid, $ml$climatetech$ml$, 15, 3, $ml${"id": "climatetech-d15-c3", "title": "Planning after the exit", "lessonTitle": "The US leaves Paris, again", "slot": 3, "type": "decide", "brief": {"headline": "You run strategy at a US manufacturer selling in Europe and California. The US formally left the Paris Agreement on January 27, 2026, the only country to quit it twice.", "kicker": "Decide how to plan when national policy flips.", "fullText": "President Trump announced the withdrawal on his first day in office, January 20, 2025. The US is now one of the few countries without a climate pollution reduction goal.\n\nCommitments last only as long as each government keeps them. Your company also answers to customers and rules in Europe and in US states, which did not change with the exit.", "sources": [{"url": "https://www.eenews.net/articles/so-long-paris-us-officially-leaves-landmark-climate-pact/", "label": "E&E News, US officially leaves the Paris pact"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The US is the only country to leave Paris twice.", "The exit took effect one year after notice.", "Leaving Paris ended all US state climate laws."], "fakeIndex": 2, "explanation": "State climate laws are separate from the federal exit and remain in force."}, "numbers": {"kind": "numberSense", "prompt": "How many parties did the Paris Agreement count after the US exit on January 27, 2026?", "min": 0, "max": 250, "value": 194, "unit": "parties", "explanation": "194 parties. Nearly every country remains in the agreement."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked to brief the leadership team on the exit.", "prompt": "What is the main point?", "options": ["Our EU and state rules still apply to us", "All our climate obligations are now gone", "We must leave the European market"], "correctIndex": 0, "consequences": ["You focus on the rules that still bind you.", "European and state rules did not change.", "The exit does not affect market access."], "explanation": "The federal exit did not change rules in Europe or in states like California."}, "proReasoning": "Good briefings separate what changed from what still applies to the business.", "commonMistake": "Telling leaders that a national exit removed every obligation.", "mentalModel": "Say what changed and what did not."}, "invest": {"call": {"kind": "theCall", "situation": "A shareholder asks whether the company should drop its climate plan.", "prompt": "How do you answer?", "options": ["Double it to make a political point", "Keep it: customers and markets still expect it", "Drop it, since the US has now left Paris for good"], "correctIndex": 1, "consequences": ["Strategy should follow customers, not politics.", "You tie the plan to business reality.", "European and state rules still apply."], "explanation": "Commitments shift with governments, but customers and other markets still set expectations."}, "proReasoning": "Shareholders value plans anchored in customers and markets, not one government's stance.", "commonMistake": "Letting one political event drive long-term strategy.", "mentalModel": "Anchor strategy to customers."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your company considers building a low-carbon product line.", "prompt": "Where is demand strongest now?", "options": ["Only federal US agencies, nothing else", "Nowhere, after the exit", "Europe and climate-committed US states"], "correctIndex": 2, "consequences": ["Federal climate demand is shrinking.", "Demand remains in many markets.", "You go where rules and buyers still push."], "explanation": "Europe and many US states kept their climate rules after the federal exit."}, "proReasoning": "Builders target markets where rules and buyers still reward low-carbon products.", "commonMistake": "Assuming one country's exit erased global demand.", "mentalModel": "Build for the markets that still reward it."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why the US could leave Paris twice.", "prompt": "What does that show?", "options": ["Promises last only while governments keep them", "Paris forbids any country from ever leaving", "The US was never really a full member of Paris"], "correctIndex": 0, "consequences": ["Each government can reverse the last.", "The agreement allows withdrawal with notice.", "It was a party twice."], "explanation": "The US joined, left, rejoined and left again as governments changed."}, "proReasoning": "Climate diplomacy depends on each government keeping its predecessor's word.", "commonMistake": "Assuming international commitments are permanent.", "mentalModel": "Commitments depend on governments."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8cce23a45e8f$ml$]::text[])
